	    //var ua = navigator.userAgent;
	    //if (ua.includes('linux')){
	    //    return true;
	    //}else{
	    //    return false;
	    //}

        var OSInfo = getOSInfo().platform;
        if (OSInfo == "LINUX") return true;
        return false;
	}
