 */
gcm.init 	= function() {

	try {
		// 공통 기능 설정
		_setCommon();

		// 공통 HTML 요소 추가
		_setCommonElement();

		// 시스템별 공통 기능 설정
		_setCommonSystem();

		// anySign 시스템별 공통 기능 설정
		_setCommonAnySign();

		// 모달 설정
		_setCommonModal();

		// 전용브라우져 초기 설정
		gcm.initWbrowser();

		// window message 설정 (외부 솔루션 연동용)
		gcm.postmessage.init();
	} catch(ex) {
		console.log(ex);
	}

	/**
	 * 함수명 	: _setCommon
	 * 함수설명	: 공통 기능 설정 (내부함수)
	 * 				- onpageunoload 이벤트 대신 처리를 위해 blank 페이지를 추가
	 * 				- IME 모드 설정 (로그인 : 영어, 다른페이지 : 한글)
	 * 				- 포커스, GridView 속성 기본 설정
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _setCommon() {

		//=======================================================
		// FloatingLayer 컴포넌트 모달 속성 추가
		//=======================================================
		com.comp.setFloating(mf);

		// onpageunoload 이벤트 비정상으로 blank 페이지를 추가
		com.page.setUnloadBlankPage(mf);

		//====================================================================
		// ime-mode 설정 (IM10 시스템 : 팝업창은 한글 / 로그인 창은 영어)
		//  - IM10 : Im10ComLogin
		//	- SM30 : Sm30UserSptSysLogin
		//	- EM40 : Em40R0Login
		//====================================================================
		var engFile = ['Im10ComLogin', 'Sm30UserSptSysLogin', 'Em40R0Login'];
		if (window.name) {
			com.page.setImeMode('Korean');
		} else {
			var urlParam	= WebSquareExternal.w2xPath;

			if (com.util.isEmpty(urlParam)) {
				com.page.setImeMode('Korean');
			} else {
				var fileNm 		= urlParam.match(/[^\/](\w|[가-힣])+(?=\.)/)[0];
				var findEngFile	= engFile.filter(function(item) {return item == fileNm});

				if (findEngFile.length == 0) {
					com.page.setImeMode('Korean');
				} else {
					com.page.setImeMode('English');
				}
			}
		}

		// 포커스 정보 초기설정 (IM10 시스템)
		window.focusInfo		= {};

		// GridView 기본 visibleRowNum, pageListSize 로드
		gcm.GRID_VISIBLE_ROWNUM = com.util.getPropertyIntValue("egov.common.pagenationpageUnit");
		gcm.PAGE_LIST_SIZE 		= com.util.getPropertyIntValue("egov.common.pagenationpageSize");


