	/**
	 * 함수명 	: _setCommonModal
	 * 함수설명	: 모달 설정 (내부함수)
	 * 				- showModal, hideModal 엔진 함수를 override 하여 모달을 처리함
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _setCommonModal() {


		WebSquare.getBody().showModal = function(e, t, o) {

			WebSquare.getBody().__proto__.showModal.apply(this, arguments);

			// 모달정보 설정 (팝업, 플로팅레이어)
			if (e && e.className && e.popupModal) {
				gcm.MODAL_INFO.push({type : 'POPUP', id : e.stackComponents.popup.id});
			} else if (e == 'w2modal_floatingLayer') {
				gcm.MODAL_INFO.push({type : 'FLOATING', id : o.floatingLayer});
			}

			_setModal();
		};

		WebSquare.getBody().hideModal = function(e, t) {

			WebSquare.getBody().__proto__.hideModal.apply(this, arguments);

			for (i = 0 ; i < gcm.MODAL_INFO.length ; i ++) {
				if (t == gcm.MODAL_INFO[i].id) {
					gcm.MODAL_INFO.splice(i, 1);
					break;
				}
			}
			_setModal();
		};


		/**
		 * 함수명 	: _setModal
		 * 함수설명	: 모달 창(FloatingLayer) z-index 설정
		 * 파라미터	: N/A
		 * 리턴		: N/A
		 * 작성일 	: 2022.09.01
		 * 작성자 	: Inswave Systems
		 */
		function _setModal() {

			if (!document.getElementById('_modal')) return;
			if (gcm.MODAL_INFO.length == 0) return;

			try {
				var modalObj	= document.getElementById('_modal');
				var modalZIndex	= com.num.parseInt(window.getComputedStyle(modalObj)['zIndex']);

				if (modalObj.style.display == 'block' && isNaN(modalZIndex) == false) {

					var isLast	= true;

					for (var i = gcm.MODAL_INFO.length -1 ; i > -1 ; i --) {

						var modalInfo	= gcm.MODAL_INFO[i];
						var modalComp	= null;

						if (modalInfo.type == 'FLOATING') {
							modalComp	= WebSquare.idCache[modalInfo.id];
						} else {
							modalComp	= window[modalInfo.id];
						}

						isLast	= (i == gcm.MODAL_INFO.length -1) ? true : false;

						if (modalInfo.type == 'FLOATING') {
							if (isLast) {
								modalComp.render.style.zIndex = modalZIndex + 1;
							} else {
								modalComp.render.style.zIndex = modalZIndex - 1;
							}
						}
					}
				}
			} catch(ex) {
				console.log(ex);
			}
		}
	}

};

/**
 * 함수명 	: gcm.initWbrowser
