/**
 * 함수명 	: gcm.win.openMenuSM30
 * 함수설명	: 메뉴를 오픈한다. (SM30용)
 * 파라미터	: $p : scope의 $p객체
 * 				menuInfo : 오픈 메뉴정보
 * 				param : 메뉴오픈 시 전달할 파라미터
 * 				closable : 닫기 가능 여부 (true)
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.win.openMenuSM30 = function($p, menuInfo, param, closable) {

	// 메뉴를 새창으로 띄운다. (window 오픈 : 사용안함)
    if (menuInfo.url == "/") {
        var url = document.location.href + "/";
        window.open(url, "", "width=1200, height=700, left=450, top=100");
    } else {

    	//=========================================================================
    	// 오픈할 정보 설정
    	//	- 메인 windowContainer 컴포먼트
    	//	- 전송 파라미터 설정 (메뉴 + 파라미터)
    	//	- URL 정보
    	//=========================================================================
    	var winObj		= $p.top().wdc_main;
        var dataObject	= {
        		type : 'json', 
        		name : 'paramData',
        		data : $.extend(menuInfo, (com.util.isNotEmpty(param)) ? param : {})
        };
        var url			= gcm.CONTEXT_PATH  + menuInfo.url;

      	//=========================================================================
        // 메뉴 열기 
        //	- menuInfo.grp_scrn_seq 열린 창 확인 
        //		- 없음 : New, 있음 : 포커스 이동
        //=========================================================================
        var tarWinObj	= winObj.getFrame(menuInfo.menu_seq, true);

        // 요청사항접수(seq_menu020101) 메뉴인 경우 10개를 초과해도 window container가 오픈되어야 한다.
        if (com.util.isEmpty(tarWinObj) && winObj.windows.length == 10) {

        	if (menuInfo.menu_seq == 'seq_menu020101') {
    			winObj.setWindowMaxNum(11);
    		} else {
    			var menu020101 = winObj.getFrame('seq_menu020101', true);

    			if (com.util.isEmpty(menu020101)) {
    				winObj.setWindowMaxNum(10);
    			}
    		}
    	}

        if (com.util.isEmpty(tarWinObj)) {

            var options = {
                title 		: menuInfo.menu_nm,
                src 		: url,
                windowTitle : menuInfo.menu_nm,
                windowId 	: menuInfo.menu_seq,
                openAction 	: "existWindow",
                frameMode 	: "wframe",
                fixed 		: false,
                closeAction : function(title) {
                	if (title === "HOME") {
                        return false;
                    } else {
                        return true;
                    }
                },
                dataObject : dataObject
            }

            // windowContainer로 메뉴 열기
            winObj.createWindow(options);
        } else {

        	// 동일한 화면일 경우 새로 추가하지 않는다. (포커스만 이동)
        	var uniqueId	= winObj.getUniqueIdByWindowId(menuInfo.menu_seq);
        	var subWinObj	= winObj.getWinInfoObj(uniqueId);

        	winObj.nowWindow	= uniqueId;
        	winObj.selectWindow();

        	tarWinObj.setDataObject(dataObject);
        	tarWinObj.setSrc(menuInfo.url, {dataObject : dataObject});
	    }
        $($(winObj.render).find('.w2windowContainer_nameLayer_close')[0]).hide();

        //=======================================================================
        // 컨텐츠 클릭 시 메뉴 windowContainer 클릭 이벤트가 발생하여 버블링 제거
    	//=======================================================================
        gcm.win.stopEvent();
    }
};


