//=============================================================================
/**
 * 팝업 관련 모듈
 *	- 엔진에서 팝업창을 오픈한 Window에서 팝업정보를 관리한다. (w2popup_singleton)
 *	- 브라우져 팝업 창을 여러개 띄웠을 경우 (팝업, 팝업 ... 팝업) window.opener를 이용해 팝업 정보를 조회해야 되기 때문에 팝업 정보를
 *	  MainWindow의 gcm.POPUP_INFO 에서 통합관리하여 사용한다. (계층구조로 관리)
 *
 * @author Inswave Systems
 * @class win
 * @namespace gcm.win
 */
// =============================================================================
gcm.popup = {};


/**
 * 함수명 	: gcm.popup.getW2popup
 * 함수설명	: 웹스퀘어 w2popup_singleton에 등록된 팝업창을 조회한다.
 * 파라미터	: id : 팝업 ID
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.popup.getW2popup = function(id) {

	var popupList	= w2popup_singleton.popupList;

	for (var i =  0; i < popupList.length ; i ++) {
		if (popupList[i].id == id || popupList[i].org_id == id) {
			return popupList[i];
		}
	}
}


/**
 * 함수명 	: gcm.popup.getPopupInfo
 * 함수설명	: 팝업정보를 조회한다.
 * 파라미터	: id : 팝업 ID
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.popup.getPopupInfo = function(id) {

	var mainWin 	= gcm.win.getMainWindow();
	var popInfo		= mainWin.gcm.POPUP_INFO;

	return _getData(popInfo, id);

	function _getData (data, id) {

		if (!data) return null;

		if (data.id == id || data.orgId == id) {
			return data;
		} else if (data.sub) {

			for (var i = 0 ; i < data.sub.length ; i ++) {
				var retData	= _getData(data.sub[i], id)

				if (com.util.isNotEmpty(retData)) {
					return retData;
				}
			}
		}
	}
};


/**
 * 함수명 	: gcm.popup.setPopupInfo
 * 함수설명	: 팝업정보를 설정한다.
 * 파라미터	: info : 팝업 정보
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.popup.setPopupInfo = function(info) {

	console.log({method : 'gcm.popup.setPopupInfo', info : info});

	// Main Window 조회
	var mainWin 	= gcm.win.getMainWindow();

	// 팝업창 정보를 저장한다. (gcm.PUPUP_INFO)
	_createParentInfo(info);


	/**
	 * 함수명 	: _createParentInfo
	 * 함수설명	: 팝업창 정보를 저장한다. (재귀함수 : gcm.PUPUP_INFO)
	 * 				- 상위 팝업창 정보에 팝업창 정보를 추가.
	 * 파라미터	: info : 팝업 정보
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _createParentInfo(info) {
		// 상위 팝업창 정보 조회
		var parentInfo	= mainWin.gcm.popup.getPopupInfo(info.parentId);
		var newParent	= {};

		//=======================================================================
		// 팝업 정보 추가
		//	- 상위팝업정보가 있을 경우 : sub에 팝업 정보 추가
		//	- 상위팝업정보가 없을 경우 : 상위 scope을 추가, 추가 하고 추가한 상위의 sub에 팝업 정보 추가
		//=======================================================================
		if (parentInfo) {
			parentInfo.sub.push(info);
		} else {
			if (info.scopeId == 'mf') {
				// 최상위 scope이면 sub에 추가함.
				newParent 	= {id : info.parentId, parentId : window.name + '_wframe', scopeId : info.scopeId, sub : [info]};
				parentInfo	= mainWin.gcm.popup.getPopupInfo(newParent.parentId);

				parentInfo.sub.push(newParent);
				return;
			}

			// 상위 scope 조회
			var scopeId	= $p.getComponentById(info.scopeId).parentControl.scope_id;		// 상위
			var parentId= '';

			// 팝업 종류에 따라 parentId 조회가 틀림
			//	- 브라우저팝업 : widnow.name
			//	- wFrame 팝업 : scopeId
			if (window.name != '') {
				parentId	= window.name + '_' + scopeId;				
				newParent 	= {id : info.parentId, parentId : parentId, scopeId : scopeId, sub : [info]};
			} else {
				parentId	= scopeId;
				newParent 	= {id : info.parentId, parentId : parentId, scopeId : scopeId, sub : [info]};
			}

			// 상위 팝업 정보 조회하여 sub에 추가 함수 호출 (재귀함수)
			_createParentInfo(newParent);
		}
	}

};


/**
 * 함수명 	: gcm.popup.searchPopup
 * 함수설명	: 팝업 정보를 검색한다.'
 * 파라미터	: popOptions : 검색 구분 옵션
 * 				popOptions.id : 팝업 ID (검색 기준이 되는 팝업창 ID)
 * 				popOptions.type : 검색 구분
 * 					- PARENT : 상위 팝업 정보 조회
 * 					- PARENT_ALL : 상위 모든 팝업 정보 조회
 * 					- CHILD : 하위 팝업 정보 조회
 * 					- CHILD_ALL : 하위 모든 팝업 정보 조회
 * 					- BROTHER : 형제 팝업 정보 조회
 * 			   searchOptions : 검색조건 (팝업창 호출 시 searchOptions에 대해 검색한다.)
 * 			   searchOptions.operator : 연결연산자 (AND (기본) : OR)
 * 리턴		: 팝업 정보 (배열)
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.popup.searchPopup = function(popOptions, searchOptions) {

	var mainWin 	= gcm.win.getMainWindow();
	var popInfo		= mainWin.gcm.POPUP_INFO;
	var thisData	= mainWin.gcm.popup.getPopupInfo(popOptions.id)
	var searchData	= [];
	var resultData	= [];

	if (com.util.isEmpty(thisData)) {
		return [];
	}

	//============================================================================
	// 검색 구분 옵션에 따른 팝업 정보 조회
	//============================================================================
	if (popOptions.type == 'PARENT') {

		_getParent(thisData.parentId);

	} else if (popOptions.type == 'PARENT_ALL') {

		_getParentAll(thisData.parentId);

	} else if (popOptions.type == 'CHILD') {

		_getChild(thisData);

	} else if (popOptions.type == 'CHILD_ALL') {

		_getChildAll(thisData);

	} else if (popOptions.type == 'BROTHER') {

		_getBrother(thisData.parentId);

	}

	//============================================================================
	// 검색 구분 옵션에 따른 팝업 정보 결과를 searchOptions을 이용하여 재검색
	//============================================================================
	if (searchOptions) {

		console.log('searchPopup');

		for (var i = 0 ; i < searchData.length ; i ++) {
			if (_isSearch(searchData[i])) {

				if (searchData[i].popType == 'wframePopup') {
					resultData.push(searchData[i]);
				} else {
					var opener 	= searchData[i].popWin.opener;
					if (opener) {
						var isPopup = opener.w2popup_singleton.popupList.filter(function(item) {
							return (searchData[i].orgId == item.id || searchData[i].orgId == item.org_id)
						});


						if (isPopup.length != 0) {
							resultData.push(searchData[i]);
						}
					}
				}
			}
		}
	} else {
		resultData	= searchData;
	}

	return resultData;


	/**
	 * 함수명 	: _getParent
	 * 함수설명	: 상위 팝업 정보를 조회한다. (재귀함수)(내부함수)
	 * 				- 상위 팝업 정보는 searchData에 추가함.
	 * 파라미터	: id : 상위 팝업 id
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _getParent(id) {

		var parentData	= mainWin.gcm.popup.getPopupInfo(id);

		if (com.util.isNotEmpty(parentData)) {
			if (com.util.isNotEmpty(parentData.popWin)) {
				searchData.push(parentData);
				return;
			} else {
				_getParent(parentData.parentId);
			}
		}
	}


	/**
	 * 함수명 	: _getParentAll
	 * 함수설명	: 상위 팝업 정보를 전체 조회한다. (재귀함수)(내부함수)
	 * 				- 상위 팝업 정보는 searchData에 추가함.
	 * 파라미터	: id : 상위 팝업 id
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _getParentAll(id) {

		var parentData	= mainWin.gcm.popup.getPopupInfo(id);

		if (com.util.isNotEmpty(parentData)) {
			if (com.util.isNotEmpty(parentData.popWin)) {
				searchData.push(parentData);
			}
			_getParentAll(parentData.parentId);
		}
	}


	/**
	 * 함수명 	: _getBrother
	 * 함수설명	: 형제 팝업 정보를 조회한다. (내부함수)
	 * 				- 상위 팝업 정보에서 하위 팝업 정보를 조회함 (_getChild)
	 * 파라미터	: id : 상위 팝업 id
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _getBrother(id) {
		var parentData	= mainWin.gcm.popup.getPopupInfo(id);

		_getChild(parentData);
	}


	/**
	 * 함수명 	: _getChild
	 * 함수설명	: 하위 팝업 정보를 조회한다.(재귀함수)(내부함수)
	 * 				- 상위 팝업 정보는 searchData에 추가함.
	 * 파라미터	: data : 팝업 정보
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _getChild(data) {

		for (var i = 0 ; i < data.sub.length ; i ++) {
			if (com.util.isNotEmpty(data.sub[i].popWin)) {
				searchData.push(data.sub[i]);
			} else {
				_getChild(data.sub[i]);
			}
		}
	}


	/**
	 * 함수명 	: _getChildAll
	 * 함수설명	: 하위 팝업 정보 전체를 조회한다. (재귀함수)(내부함수)
	 * 				- 하위 팝업 정보는 searchData에 추가함.
	 * 파라미터	: data : 팝업 정보
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _getChildAll(data) {

		for (var i = 0 ; i < data.sub.length ; i ++) {			

			if (com.util.isNotEmpty(data.sub[i].popWin)) {
				searchData.push(data.sub[i]);
			}
			_getChildAll(data.sub[i]);
		}
	}


	/**
	 * 함수명 	: _isSearch
	 * 함수설명	: 검색 구분 옵션으로 조회한 팝업 정보를 searchOptions 정보로 재조회(내부함수)
	 * 파라미터	: data : 검색한 팝업 정보
	 * 리턴		: 여부 (true / false)
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _isSearch(data) {

		var addInfo		= {};
		var operator	= searchOptions.operator || 'AND';

		//=================================================================
		// searchOptions 옵션 검색 결과 (true / false) 정보 addInfo 저장
		//=================================================================
		for (var item in searchOptions) {

			if (!com.util.isArray(searchOptions[item])) {
				searchOptions[item] = [searchOptions[item]];
			}

			var searchVal = (com.util.isArray(searchOptions[item])) ? searchOptions[item] : [searchOptions[item]];

			if (item != 'operator') {

				var isFind	= searchVal.filter(function(val) {
					return val == data.searchInfo[item];
				});

				if (isFind.length == 0 ) {
					addInfo[item] = false;
				} else {
					addInfo[item] = true;
				}
			}
		}		

		//=================================================================
		// searchOptions.operator (AND / OR) 연산자 적용 재검색
		//=================================================================
		if (operator == 'AND') {
			var isAdd	= true;

			for (var item in addInfo) {
				if (!addInfo[item]) {
					isAdd	= false;
					break;
				}
			}
			return isAdd;
		} else if (operator == 'OR') {
			var isAdd	= false;

			for (var item in addInfo) {
				if (addInfo[item]) {
					isAdd	= true;
					break;
				}
			}
			return isAdd;
		}		
		return false;
	}
};


/**
 * 함수명 	: gcm.popup.clearPopupInfo
 * 함수설명	: 팝업 정보를 제거한다.
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.popup.clearPopupInfo = function() {

	var mainWin 	= gcm.win.getMainWindow();
	var popInfo		= mainWin.gcm.POPUP_INFO.sub;

	// 팝업정보 제거
	_clearPopup(popInfo);


	/**
	 * 함수명 	: _clearPopup
	 * 함수설명	: 팝업 정보를 제거한다. (내부함수)
	 * 파라미터	: data : 팝업 정보
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _clearPopup(data) {
		for (var i = data.length -1 ; i > -1 ; i --) {

			if (data[i].popWin) {
				_clearPopup(data[i].sub);
			} else {
				var childObj	= gcm.popup.searchPopup({id : data[i].id, type : 'CHILD_ALL'});

				if (childObj.length == 0) {
					data.splice(i, 1);
				} else {
					_clearPopup(data[i].sub);
				}
			}
		}	
	}
};




