/**
 * 함수명 	: gcm.data.getWasPropertyURL
 * 함수설명	: 프로퍼티 조회 서비스 URL을 조회한다. (WAS별로 URL이 틀림)
 * 				- gcm.SYS_PROPERTY_URL에 등록되어 있는 경우 gcm.SYS_PROPERTY_URL에서 조회 후 리턴
 * 				- gcmSYS_PROPERTY_URL에 미등록되어 있는 경우 gcm.data.getWasPropertyURLValue 서비스를 호출 후 리턴된 URL을 gcm.SYS_PROPERTY_URL에 저장하고 URL 리턴
 * 파라미터	: wasSysId : WAS 시스템 코드
 * 			  type : 프로퍼티 유형 (string, int, long)
 * 리턴		: 프로퍼티 조회 서비스 URL
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.data.getWasPropertyURL = function(wasSysId, type) {

	var webSysId	= gcm.SYS_ID.toLowerCase();

	if (webSysId == 'em40' || webSysId == 'pm20' || webSysId == 'pm60' || webSysId == 'sm30') {
		return gcm.SYS_PROPERTY_URL['egov'][type];
	}

	if (gcm.SYS_PROPERTY_URL[wasSysId] && gcm.SYS_PROPERTY_URL[wasSysId][type]) {
		return gcm.SYS_PROPERTY_URL[wasSysId][type];
	} else {
		var propertyCd	= {
			string 	: webSysId + '.websquare.Property.string.' + wasSysId + '.url',
			int		: webSysId + '.websquare.Property.int.' + wasSysId + '.url',
			long	: webSysId + '.websquare.Property.long.' + wasSysId + '.url',
		};

		var url	= gcm.data.getWasPropertyURLValue(type, propertyCd[type]);

		if (com.util.isEmpty(gcm.SYS_PROPERTY_URL[wasSysId])) {
			gcm.SYS_PROPERTY_URL[wasSysId]	= {};
		} 
		gcm.SYS_PROPERTY_URL[wasSysId][type] = url;

		return url;
	}
};


