/**
 * Submission 관련 모듈
 *
 * config.xml에 정의된 Submission PreSubmit, CallSubmitFunc, ExnteralHandler 함수를 gcm.sbm 객체 아래에 기술.
 *
 * @author Inswave Systems
 * @class sbm
 * @namespace gcm.sbm
 */
// =============================================================================

gcm.sbm = {};


/**
 * 함수명 	: gcm.sbm._endSubmission
 * 함수설명	: 페이지 scwin.endPageFn 함수에서 사용하는 submission
 * 파라미터	: sbmObj : submission
 * 			  newRef : submission 전송 정보
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.sbm._endSubmission = function(sbmObj, newRef) {

	var id		= '__end_sbm_' + com.num.random();
	var options = {
    	id 			: id,
    	action 		: sbmObj.action,
    	method 		: sbmObj.method,
    	mediatype	: sbmObj.mediatype,
    	mode 		: 'synchronous',
    	processMsg 	: '$blank',
    	ref			: newRef,
    	target		: sbmObj.target
    };

    var endSbmObj	= com.sbm.create(options);

    endSbmObj.mNoMessage = true;

    $p.executeSubmission(endSbmObj);

    // Submission을 실행 후 삭제한다.
    $p.deleteSubmission(id);

    WebSquare.layer.hideProcessMessage();
};


