/**
 * 함수명 	: gcm.data._callbackSubmitFunction
 * 함수설명	: Submission 전송 결과를 처리한다.(오류, 에러메시지 ..)
 * 				- config.xml에 정의됨.
 * 				- 서버 에러 메시지 리턴 시 에러 메시지 창 호출
 * 				- 에러가 발생한 경우 submission의 submissiondone 이벤트가 발생하지 않는다.
 * 파라미터	: resData : 결과데이터
 * 			  sbmObj : submission 컴포넌트
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 *        2026.01.29  [2025-W00938] 하자보수담당자(인터넷) [하자] 인터넷등기소 일부서비스 중단 시 현재 페이지에서 이벤트 호출 가능한 현상 조치 
 * 작성자 	: Inswave Systems
 */
gcm.sbm._callbackSubmitFunction = function(resData, sbmObj) {

	console.log({method : 'gcm.sbm._callbackSubmitFunction' , mode : sbmObj.mode, processMsg : sbmObj.processMsg, data : resData});

	if (sbmObj && sbmObj.mNoMessage == true) return;

	// processMsg 복원
	if (sbmObj.mMode) sbmObj.mode = sbmObj.mMode;

	var callbackFlag	= false;

	//=======================================================================
	// 500 에러 발생 시 에러 데이터 생성
	//=======================================================================
	if (resData.responseStatusCode == '500') {
		resData.responseJSON = {
			'class'					: '500 error',
			'nrsMessageArgs'		: '',
			'nrsMessageCallBackFn'	: '',
			'nrsMessageCd'			: 'egov.message.error.web.com.error',
			'nrsMessagePopupYn'		: '',
			'nrsMessageRtnUri'		: '',
			'nrsMessageTitle'		: '오류',
			'nrsMessageType'		: 'error',
			'nrsMessageValue'		: '시스템 오류가 발생했습니다.',
		};
	}

	//=======================================================================
	// 서버 에러 메시지가 있을 때 에러 메시지 창 띄움
	//	- 로그아웃 메시지 : 로그인 페이지로 이동
	//	- 에러에 대한 콜백이 있는 경우
	//		- 화면콜백 + 서버콜백 : 화면콜백 호출
	//		- 화면콜백 : 화면콜백 호출
	//		- 서버콜백 : 서버콜백 호출
	//	- 에러 메시지 창 띄움
	//=======================================================================
	if (com.util.isNotEmpty(resData.responseJSON)) {
		if (com.util.isNotEmpty(resData.responseJSON.nrsMessageCd)) {

			// 로그아웃 메시지일 경우 로그인 화면으로 이동 시킴.
			if (resData.responseJSON.nrsMessageCd == 'egov.message.error.web.com.login') {
				if (gcm.SYS_ID === "PM10") gcm.FORWARD_LOGIN_YN = "Y";

				com.message.logout();
				callbackFlag	= true;
			} else if(resData.responseJSON.nrsMessageCd == 'egov.message.info.web.com.0014'){
				//$p.navigate("/html/pm10/com/Pm10ComServiceCheck.html");
				window.location.href = "/html/pm10/com/Pm10ComServicePartCheck.html";
			} else {

				// 화면 Exception, 서비스 Exception Callback 함수
				var execptionCallbackFn	= null;
				try {
					if (sbmObj.exceptionCallbackFn) {
						execptionCallbackFn	= sbmObj.exceptionCallbackFn;
					} else {

						// 서비스 Exception Callback
						if (resData.responseJSON.nrsMessageCallBackFn != '') {
							var scope	= sbmObj.getScopeWindow();
							var func	= resData.responseJSON.nrsMessageCallBackFn.split('.');

							execptionCallbackFn	= scope[func[0]][func[1]];
						}
					}
				} catch(e) {
					execptionCallbackFn = null;
				}

				//시스템 에러 메시지 출력 (메시지가 있는 경우 띄우지 않음)
				if (com.message.isOpenMessage() == false) {
					com.message._openMessage({
						popId			: 'SYSTEM_ERROR_POPUP' + com.num.random(),
						messageType 	: resData.responseJSON.nrsMessageType,
						messageTitle 	: resData.responseJSON.nrsMessageTitle,
						message 		: resData.responseJSON.nrsMessageValue,
						messageData		: resData.responseJSON,
						callerId		: (sbmObj.scope_id) ? sbmObj.scope_id : '',
					}, execptionCallbackFn);
				}
				callbackFlag	= true;
			} 
		}
	}

	//=======================================================================
	// 콜백 이벤트 실행 및 중지 설정
	//	- 오류 : 콜백 이벤트 중지
	//	- 성공 : 콜백 이벤트 실행
	//=======================================================================
	if (sbmObj.userEventList) {
		for (var i = 0; i < sbmObj.userEventList.length; i++) {
			sbmObj.userEventList[i].disabled = callbackFlag;
		}
	}

	return (callbackFlag) ? false : true;
};


