 * DATE : 2020.02.06
 * AUTH : 오성식
 */
EgovNrsDateBase.gfn_nationalDays = function(date) {
 for (i = 0; i < EgovNrsDateBase.natDays.length; i++) {
  if (date.getFullYear() == EgovNrsDateBase.natDays[i][0] && date.getMonth() == EgovNrsDateBase.natDays[i][1] - 1
                    && date.getDate() == EgovNrsDateBase.natDays[i][2]) {       
   return [true, EgovNrsDateBase.natDays[i][3] + '_day',EgovNrsDateBase.natDays[i][4]];
  }
 }
 return [true, ''];
};

/**
 * 날짜 크기 비교
 *
 * DATE : 2021.12.30
 * AUTH : 최태석
 */
EgovNrsDateBase.gfn_dateCompare = function(strDate1,strDate2){
    
    var tmp_date1 = EgovNrsStringBase.gfn_specialRemove(strDate1, '.') + "";
    var tmp_date2 = EgovNrsStringBase.gfn_specialRemove(strDate2, '.') + "";
    var iRet = -2;
    
    if (tmp_date1 == tmp_date2)
    {
        iRet = 0;
    }
    else if (tmp_date1 > tmp_date2)
    {
        iRet = 1;
    }
    else if (tmp_date1 < tmp_date2)
    {
        iRet = -1;
    }
    
    if (iRet == -2)
    {
        alert("날자 비교가 잘못 되었습니다.");
    }
    
    return iRet;

};

/**
 * 날짜 포맷 검증
 *
 * DATE : 2021.12.30
 * AUTH : 최태석
 */
EgovNrsDateBase.gfn_Str2dt = function(strDate) {

    strDate = strDate.substring(0,4) + "-" + strDate.substring(4,6) + "-" + strDate.substring(6,8);
    
    var reDate = /^(\d+)\-(\d+)\-(\d+)$/;
    
    if (!reDate.exec(strDate))
        return alert("Invalid Datetime format: "+ strDate);
    return (new Date (RegExp.$1, RegExp.$2-1, RegExp.$3));
};


