/**
 * gfn_ShowCalendar 에서 호출
 *
 * DATE : 2021.12.30
 * AUTH : 최태석
 */
EgovNrsDateBase.gfn_strDt2dt = function(strDateTime){
    
    var returnYear  = new String (strDateTime.getFullYear());
    var returnMonth = new String (strDateTime.getMonth()+1);
    var returnDate  = new String (strDateTime.getDate());

    if (returnMonth.length < 2) returnMonth = "0" + returnMonth;
    if (returnDate.length < 2)  returnDate = "0" + returnDate;

    return returnYear + returnMonth + returnDate;
};

/**
 * 입력받은 달에 일수
 *
 * DATE : 2021.12.30
 * AUTH : 최태석
 */
EgovNrsDateBase.gfn_getDayCount = function(strYear, strMonth) {

        var iyear = eval(strYear);
        var imonth = eval(strMonth);
        var day_term = new Array(31,28,31,30,31,30,31,31,30,31,30,31);
        
        if (imonth==2 && (iyear/4==Math.floor(iyear/4) || iyear/400==Math.floor(iyear/400))) {
            return 29;
        }
        else return day_term[imonth-1];
};

/**
 * 두 날짜 사이의 일수
 *
 * DATE : 2021.12.30
 * AUTH : 최태석
 */
EgovNrsDateBase.gfn_getBetDateCnt = function(strDate1,strDate2) {
    
    var diffTime    = strDate2.getTime() - strDate1.getTime();
    
    var diffDay     = 0;
    
    if (diffTime < 0){
        diffDay     = -1;
    } else {        
        diffDay     = Math.ceil(diffTime / (1000 * 3600 * 24));
    }

    return diffDay;
};

