/**
 * 현재시각을 얻어온다.
 *
 * DATE : 2019.01.25
 * AUTH : 오성식
 */
EgovNrsDateTime.gfn_getCurrentTime = function() {

    var dt = new Date();
    var yyyy = dt.getFullYear();
    var mm = dt.getMonth() + 1;
    var dd = dt.getDate();
    var dttm = ""+yyyy + mm + dd + dt.getHours() + dt.getMinutes() + dt.getSeconds();

    //console.log("--yyyy="+yyyy+", mm="+mm+", dd="+dd+", Hour="+dt.getHours()+", Minute="+dt.getMinutes()+", Second="+dt.getSeconds());

    return dttm;
};

