EgovNrsLoadPage.gfn_loadPage = function(type, url, params, divId, callback) {
	$('#'+divId).html("");
	var exceptionMsg = "예기치 못한 에러가 발생하였습니다. 잠시 후 사용해 주십시오.";
	try {
		console.log("=========AJAX gfn_loadPage START");
		$.ajax({
				type:type,
				url:url,
				data:params,
				dataType: "HTML",
				cache: false
		}).done(function(htmlPage) {

			$('#'+divId).html(htmlPage);
			
			if( typeof callback === 'function' ){
				callback();
			}
			//$('body').mLoading('hide'); //로딩바 닫기
		}).fail(function(htmlPage){
			alert(exceptionMsg);
			//$('body').mLoading('hide'); //로딩바 닫기
		});
	} catch(e) {
		alert(exceptionMsg);
		//$('body').mLoading('hide'); //로딩바 닫기
	}
	return;
};

