// 공통함수를 공통 객체로 선언 (파일명과 동일)
var EgovNrsStringFormat = {};  // 공통함수 객체 선언

/**
 * 입력한 값에 대해서 , 를 붙여준다.
 *    
 * @param id (strValue)
 * @return String
 *
 * DATE : 2021.12.10
 * AUTH : 최태석
 */
EgovNrsStringFormat.gfn_comma = function(strValue){

    var numValue = "";
    var retValue = "";
    
    if(EgovNrsNumberBase.gfn_checkOnlyNumber(strValue,"입력값은") == false){
        return;
    }
    
    
    try {
        numValue = "" + strValue + "";

        for (i = 0; i < numValue.length; i++) {
            if (i > 0 && (i % 3) == 0)
                retValue = strValue.charAt(strValue.length - i - 1) + "," + retValue;
            else
                retValue = strValue.charAt(strValue.length - i - 1) + retValue;
        }
        return retValue;
    }catch (e) {
        alert(e.description);
    }
};

