 * 함수설명 : 서브미션 후 처리 함수 
 * 파라메터 : 서브미션 오브젝트
 * 리턴     : 
 * 작성일   : 2023.09.11
 * 작성자   : 
 */
Pm10ComGlobal.gfn_afterExecuteSubmission = function(obj) {
	var submissionId = obj.id
	var notExistsList = [
		  "callbackSubmitFunction"
		, "sbm_commCodeGlobal"
		, "sbm_commXmlDataGlobal"
		, "sbm_isLoginCheck"
		, "sbm_getPropertyInt"
		, "sbm_getSystemProperty"
		, "sbm_isEnvTypeCheck"
		, "sbm_isDevModeCheck"
		, "sbm_getConnectServerInfo"
		, "sbm_isIrosPageCheck"
		, "sbm_getMessage"
		, "sbm_getMenuRigtCheck"
		, "sbm_getMenuRigtValCheck"
		, "sbm_EgovNrsSessionBaseCtrl_getSessionBaseVo"
		, "sbm_Pm10P0MainScrnMngCtrl_retrieveMainScrn"
		, "sbm_Pm10P0MainScrnMngCtrl_retrieveMenuList"
		, "sbm_Pm10P0IntgSrchMngCtrl_retrieveRecommandSwrd"
		, "sbm_Pm10ComSessionBaseCtrl_getSeverEnvInfo"
		, "sbm_Pm10ComSessionBaseCtrl_getIsValidSsoToken"
		, "sbm_Pm10ComSessionBaseCtrl_getSessionVal"
		, "sbm_Pm10ComSessionBaseCtrl_getNmbrSessionVal"
		, "sbm_Pm10ComSessionBaseCtrl_deleteSession"
		, "sbm_Pm10ComSessionBaseCtrl_deleteNmbrSession"
		, "sbm_Pm10ComSessionBaseCtrl_executeNmbrLogoutHeader"
		, "sbm_Pm10ComSessionBaseCtrl_executeLogout"
		, "sbm_Pm10ComSessionBaseCtrl_executeNmbrLogout"
	];
	var existsYn = "N";
	for(var idx = 0; idx < notExistsList.length; idx++){
		if(submissionId.includes(notExistsList[idx])){
			existsYn = "Y";
			break;
		}
	}
	if(existsYn == "N"){
		//com.page.getMainPage().wfm_potal_main.scope.wf_header.scope.scwin.refreshSessionTime();
		var sbmInfo = "";
		if(submissionId.split("sbm_").length > 1){
			sbmInfo = "sbm_" + submissionId.split("sbm_")[1];
		}else{
			sbmInfo = submissionId;
		}
		var actionInfo = obj.action.split("?")[0];
		console.log("## 통합테스트용 콘솔 로그 - EXECUTE_SUBMISSION :: SUBMISSION_ID:" + sbmInfo + ", SUBMISSION_URL:" + actionInfo);
	}
};

