 * @example : Pr10ComUtil.gfn_rtrim(ibx_admin_regn3.getValue())
 */	
Pr10ComUtil.gfn_rtrim = function(str) {
	while (str.substring(str.length - 1, str.length) == ' ') {
		str = str.substring(0, str.length - 1);
	}
	
	return str;
}	
	

