/**
 * 함수명   : Pr10ComUtil.gfn_today
 * 함수설명 : 전달받은 파라미터(날짜 문자열) 현재일 이후 일자인지 검증한다.
 * 파라메터 : {String} 검증대상 입력 문자열(날짜)
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 이숙정
 * @example : if( Pr10ComUtil.gfn_today(ibx_rgs_caus_date.getValue())!=true){
 * 					com.win.openMessagePopup("error", "egov.message.title.web.Pr10ComUtil.error", "pr10.message.error.web.Pr10ComUtil.0003", "등기원인일자");
 *  				return false;
 * 			  }
 */	
Pr10ComUtil.gfn_today = function(strDate){
	var today = new Date();
	var yyyy = today.getFullYear();
	var mm = today.getMonth() + 1;
	var dd = today.getDate();

	var chg_date = strDate.substr(0, 4) + strDate.substr(4, 2) + strDate.substr(6, 2);

