	mm = Pr10ComUtil.gfn_formatFillZeroByValue(mm, 2);
	dd = Pr10ComUtil.gfn_formatFillZeroByValue(dd, 2);

	if (chg_date > yyyy + mm + dd) {
		return false;
	}

	return true;
}
	
	
/**
 * 함수명   : Pr10ComUtil.gfn_intFigure
 * 함수설명 : 전달받은 파라미터(실수)의 정수부 유효숫자 자리수 확인한다.
 * 파라메터 : {String} 검증대상 입력 실수
 *          : {int} 정수부 유효숫자 자리수
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 이숙정
 * @example : 
 */	
Pr10ComUtil.gfn_intFigure = function(iVal, size) {

	var minus = (iVal.charAt(0) == '-') ? '-' : '';
	var dot = ''; // 소수점

	var str = new String(Pr10ComUtil.gfn_delHyphen(iVal));
	var str_dot = '';// 소수점 이하 문자열
	str = Pr10ComUtil.gfn_delComma(str);

	var dot_index = 0;
	var int_str = '';// 정수부 숫자열
	var int_len = 0;// 정수부 유효숫자 자리 길이

	if ((str == '') || (str.length == 0)) {
		return true;
	}

	for (i = 0; i < str.length; i++) {
		if (!com.num.isNumber(str.charAt(i))) {
			if (str.charAt(i) == '.') {
				dot_index = i;
				break;
			}
		}
	}// end for

	if (dot_index > 0) { // 소수점이 있다면
		int_str = str.substring(0, dot_index);
		str_dot = str.substring(dot_index + 1);
		dot = '.';
	} else if (dot_index == 0) {
		int_str = str;
	}

	int_len = int_str.length;

	if (int_len > size) {
		str = str.substring(0, size);
		obj = minus + str + dot + str_dot;
		return false;
	}

	return true;
}
	

/**
 * 함수명   : Pr10ComUtil.gfn_realFigure
 * 함수설명 : 전달받은 파라미터(실수)의 소수점이하 유효숫자 자리수 확인한다.
 * 파라메터 : {String} 검증대상 입력 실수
 *          : {int} 소수점이하 유효숫자 자리수
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 이숙정
 * @example : 
 */
Pr10ComUtil.gfn_realFigure = function(dVal, size) {
	var dot_position = dVal.indexOf('.');
	var str_before_dot = '';
	var dot = '';

	if (dot_position != -1) {
		str_before_dot = dVal.substring(0, dot_position);
	}

	var str = new String(Pr10ComUtil.gfn_delComma(dVal));
	var dot_index = 0;
	var dot_under_str = '';// 소수점이하 숫자열
	var dot_under_len = 0;// 소수점이하 숫자열의 길이

	if ((str == '') || (str.length == 0)) {
		return true;
	}

	for (i = 0; i < str.length; i++) {
		if (!com.num.isNumber(str.charAt(i))) {
			if (str.charAt(i) == '.') {
				dot_index = i;
				break;
			}
		}
	}// end for

	if (dot_index > 0) {// 소수점이 있다면
		dot_under_str = str.substring(dot_index + 1);
		dot_under_len = dot_under_str.length;
		dot = '.';
		if (dot_under_len > size) {
			dot_under_str = dot_under_str.substring(0, size);
			obj = str_before_dot + dot + dot_under_str;

			return false;
		}
	}

	return true;
}


/**
 * 함수명   : Pr10ComUtil.gfn_fillZero
 * 함수설명 : 전달받은 파라미터(실수)의 실수의 정수부 .4 -> 0.4로 변환하여 반환한다.
 * 파라메터 : {String} 변환대상 입력 문자열(실수)
 * 리턴     : {String} 변환결과 문자열
 * 작성일   : 2022.05.01
 * 작성자   : 이숙정
 * @example : Pr10ComUtil.gfn_fillZero(lbx_amt.getValue())
 */		
Pr10ComUtil.gfn_fillZero = function(str) {

	var strObj = "";
	var dot = ''; // 소수점
	var str_dot = '';// 소수점 이하 문자열

	var dot_index = 0;
	var int_str = '';// 정수부 숫자열
	var int_len = 0;// 정수부 유효숫자 자리 길이

	str = new String(Pr10ComUtil.gfn_delHyphen(str));
	str = Pr10ComUtil.gfn_delComma(str);

	for (i = 0; i < str.length; i++) {
		if (!com.num.isNumber(str.charAt(i))) {
			if (str.charAt(i) == '.') {

				dot_index = i;

				if (dot_index == 0) {// 소수점이 있다면
					int_str = 0;
					str_dot = str.substring(dot_index + 1);
					dot = '.';

					int_str = int_str + dot + str_dot;

					dot_index = 100;

				} else if (dot_index > 0) {// 소수점이 있다면
					int_str = str.substring(0, dot_index);
					str_dot = str.substring(dot_index + 1);
					dot = '.';

					int_str = int_str + dot + str_dot;
				}
			}
		}
	}// end for

	if (dot_index == 0) {// 소수점이 없다
		int_str = str;
	}

	return int_str;
}

