/**
 * 함수명   : Pr10ComUtil.gfn_verifyInputChar
 * 함수설명 : 입력문자 검증
 * 파라메터 : 검증값(Char or CharCode), 검증타입(String or Array), 널인경우 리턴값(Default : false)
 * 리턴     : 검증결과
 * 작성일   : 2022.08.29
 * 작성자   : 윤영국
 */
Pr10ComUtil.gfn_verifyInputChar = function(vrfyVal, vrfyType, isNullTrue) {
	
	// 입력값이 empty인 경우 리턴값 (default : false)
	isNullTrue = isNullTrue === true ? isNullTrue : false;

	if (Pr10ComBase.gfn_isEmpty(vrfyVal)) {
		return isNullTrue;
	} else if (Pr10ComBase.gfn_isNotEmpty(vrfyType)) {
		
		// 검증유형이 String인 경우 Array 생성
		if (com.util.isString(vrfyType)) {
			vrfyType = [vrfyType];
		}
		
		// 검증유형이 Array인 경우 체크 시작
		if (com.util.isArray(vrfyType)) {
			
			var checkCode = -1;
			var checkVal = vrfyVal;
			
			// 검증값이 Char인 경우
			if (com.util.isString(vrfyVal)) {
				checkCode = vrfyVal.charCodeAt(0);
				
			// 검증값이 CharCode인 경우
			} else if (com.num.isNumber(vrfyVal)) {
				checkCode = vrfyVal;
				checkVal = String.fromCharCode(checkCode);
			}
			
			// 입력값 검증
			if (checkCode > -1) {
				// 검증유형별 체크
				var len = vrfyType.length;
				for (var i = 0; i < len; i++) {
					
					switch (vrfyType[i]) {
						case "numeric":
							if (checkCode >= 48 && checkCode <= 57) {
								return true;
							}
							break;
						case "korean":
							if (checkCode >= 44032 && checkCode <= 55203) {
								return true;
							}
							break;
						case "chinese":
							if ((checkCode >= 19968 && checkCode <= 40869)
									|| (checkCode >= 63744 && checkCode <= 64045)) {
								return true;
							}
							break;
						case "alphabet":
							if ((checkCode >= 65 && checkCode <= 90) || (checkCode >= 97 && checkCode <= 122)) {
								return true;
							}
							break;
						case "noalphabet":
							if (!Pr10ComUtil.gfn_verifyInputChar(checkCode, "alphabet")) {
								return true;
							}
							break;
						case "crlf":
							if (checkCode == 10 || checkCode == 13) {
								return true;
							}
							break;
						default:
							// 특수문자 등
							if (vrfyType[i].indexOf(checkVal) > -1) {
								return true;
							}
					}
				}
			}
		}
	}
	return false;
}

