     if(cmd == "real") {
         cstr = "0123456789.-";        //실수
     } else if(cmd == "real2") {
         cstr = "0123456789.";         //양의실수
     } else if(cmd=="int"){
         cstr="0123456789-";           //정수
     } else if(cmd=="money"){
         cstr="0123456789,";           //금액
     } else if(cmd == "real3"){
         cstr = "0123456789.-,";       //실수 : , 포함
     }else if(cmd=='numeric'){
         cstr = "0123456789";          //숫자
     }
     
     //거꾸로 돌려야 함
     if(instr.length) {
         var len = instr.length;
         for(var i = len - 1;  i >= 0; i--) {
             if(cstr.lastIndexOf(instr.charAt(i)) == -1) {
                 instr = instr.substring(0, i)+ instr.substring(i+1);
                 obj.setValue(instr);
             }
         }
     }
}

/**
 * 함수명   : Pr10ComUtil.gfn_copyDataCollection
 * 함수설명 : 데이터 컬렉션 복사
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.09.07
 * 작성자   : 윤영국
 */
Pr10ComUtil.gfn_copyDataCollection = function(srcObj, trgtObj) {
	
	var check = false;
	var srcPluginName = "src", trgtPluginName = "trgt";
	
	// source DataCollection
	if (srcObj && srcObj.options) {
		srcPluginName = srcObj.options.pluginName;
	}
	// target DataCollection
	if (trgtObj && trgtObj.options) {
		trgtPluginName = trgtObj.options.pluginName;
	}
	
	// source와 target이 동일한 경우에만 처리
//	if (srcPluginName && srcPluginName == trgtPluginName) {
//		check = true;
//	}
	// DataMap과 DataList만 처리
	if (srcPluginName == "dataMap" || srcPluginName == "dataList") {
		check = true;
	}
	
	if (check === true) {
		
		// Source DataCollection 정보
		var srcInfo = srcObj.getInfo();
		if (srcInfo) {
			// 컬럼정보
			var columnInfo = srcPluginName == "dataMap" ? srcInfo.keyInfo : srcInfo.columnInfo;
			if (columnInfo) {
				var colInfo = [];
				for (var prop in columnInfo) {
					if (columnInfo.hasOwnProperty(prop)) {
						colInfo.push(columnInfo[prop]);
					}
				}
				if (colInfo.length > 0) {
					var trgtInfo = trgtObj.getInfo();
					var scope = srcObj.getScopeWindow();
					
					// DataCollection 생성
					if (trgtInfo && scope) {
						var initData = null;
						if (trgtPluginName == "dataMap") {
							if (srcPluginName == "dataMap") {
								initData = srcObj.getJSON();
								
							// source가 DataList면 첫번째 데이터 등록
							} else if (srcPluginName == "dataList") {
								initData = srcObj.getRowJSON(0);
							}
							return scope.com.data.createDataMap(trgtInfo.dataMapInfo.id, colInfo, initData);
						} else if (trgtPluginName == "dataList") {
							if (srcPluginName == "dataMap") {
								initData = [srcObj.getJSON()];
								
							// source가 DataMap이면 한 건 등록
							} else if (srcPluginName == "dataList") {
								initData = srcObj.getAllJSON();
							}
							return scope.com.data.createDataList(trgtInfo.dataListInfo.id, colInfo, initData);
						}
					}
				}
			}
		}
	}
}

/**
 * 함수명   : Pr10ComUtil.gfn_setInputFormat
 * 함수설명 : 입력포맷설정
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.09.14
 * 작성자   : 윤영국
 */
Pr10ComUtil.gfn_setInputFormat = function(inputComp, formatType) {
	
	// 입력 컴퍼넌트 체크
	if (!inputComp) {
		return;
	}
	
	// 입력값 체크
	var val = inputComp.getValue ? inputComp.getValue() : "";
	if (Pr10ComBase.gfn_isEmpty(val)) {
		return;
	}
	
	// 포맷적용값 세팅
	if (inputComp.setValue) {
		inputComp.setValue(Pr10ComUtil.gfn_getFormattedText(val, formatType));
	}
}

Pr10ComUtil.gfn_getFormattedText = function(val, formatType) {
	if (Pr10ComBase.gfn_isEmpty(val)) {
		return "";
	}
	
	var retVal = val;
	switch (formatType) {
	
		// 주민등록번호(######-#######)
		case Pr10ComBase.FORMAT_R_ENR_NO :
			retVal = val.replace(/[^0-9]/g, "").substring(0, 13).replace(/^(\d{0,6})(\d{0,7})$/g, "$1-$2").replace(/\-$/g, "");
			break;
			
		// 납부번호(##-##-########-#)
		case Pr10ComBase.FORMAT_ENR_CASH_NO :
			retVal = val.replace(/[^0-9]/g, "").substring(0, 13).replace(/^(\d{0,2})(\d{0,2})(\d{0,8})(\d{0,1})$/g, "$1-$2-$3-$4").replace(/\-$/g, "");
			break;
			
		default :
	}
	return retVal;
}

/**
 * 함수명   : Pr10ComUtil.gfn_setAllowChar
 * 함수설명 : 입력 컴포넌트의 허용 입력문자를 설정한다.
 * 파라메터 : 입력컴포넌트, 허용문자정규식
 * 리턴     : N/A
 * 작성일   : 2022.09.30
 * 작성자   : 윤영국
 */
Pr10ComUtil.gfn_setAllowChar = function(compObj, allowChar) {
	if (compObj.options.pluginName == 'textarea') {
		compObj.validator.commandList.push(new WebSquare.validator.allowCharCommand(allowChar));
		compObj.event.addListener(compObj.render, "onkeydown", function(e) {
			if (allowChar.indexOf("\\n") < 0 && e.keyCode == 13) {
				e.returnValue = false;
			}
		});
	} else {
		if (compObj.setAllowChar) {
			compObj.setAllowChar(allowChar);
			compObj.options.validateOnInput = true;
		}
	}
}

/**
 * 함수명   : Pr10ComUtil.gfn_getFileNameFromFullPath
 * 함수설명 : 파일 경로로부터 파일명을 추출한다.
 * 파라메터 : 파일전체경로
 * 리턴     : 파일명
 * 작성일   : 2022.11.04
 * 작성자   : 윤영국
 */
Pr10ComUtil.gfn_getFileNameFromFullPath = function(fullPath) {
	var fileName = fullPath;
	
	var index = fullPath.lastIndexOf("\\");
	if (index == -1) {
		index = fullPath.lastIndexOf("/");
	}
	
	if (index != -1) {
		fileName = fullPath.substring(index + 1);
	}
	
	return fileName;
}

