/**
 * 함수명   : gfn_chkUserPin
 * 함수설명 : 사용자등록번호 형식 확인
 * 파라메터 : 입력 컴포넌트
 * 리턴     : N/A
 * 작성일   : 2022.12.27
 * 작성자   : 강명진
 */
Pr10ComUtil.gfn_chkUserPin = function(objValue) {
	var case1 = "false";
    var case2 = "false";
    var case3 = "false";
    var case4 = "false";
    var val_str_chk = 0;                            //입력불가 문자 체크
    var val_chk = 0;                                //문자조합체크
    var confirm_msg = "";                             //알림메시지

    if (objValue.getValue() != "")
    {
        for (var idx=0 ; idx < objValue.getValue().length ; idx++)
        {

            if ((objValue.getValue().charCodeAt(idx) >= 65 && objValue.getValue().charCodeAt(idx) <= 90))//영대문자
            {
                if (case1 != "true"){
                    case1 = "true";
                    val_chk++;
                }
                val_str_chk++;
            }
            if ((objValue.getValue().charCodeAt(idx) >= 97 && objValue.getValue().charCodeAt(idx) <= 122 ))//영소문자
            {
                if (case2 != "true"){
                    case2 = "true";
                    val_chk++;
                }
                val_str_chk++;
            }
            if ((objValue.getValue().charCodeAt(idx) >= 48 && objValue.getValue().charCodeAt(idx) <= 57 ))//숫자
            {
                if (case3 != "true"){
                    case3 = "true";
                    val_chk++;
                }
                val_str_chk++;
            }
            if (( objValue.getValue().charCodeAt(idx) == 126// ~
                ||objValue.getValue().charCodeAt(idx) == 96    // '
                ||objValue.getValue().charCodeAt(idx) == 33 // !
                ||objValue.getValue().charCodeAt(idx) == 64 // @
                ||objValue.getValue().charCodeAt(idx) == 35 // #
                ||objValue.getValue().charCodeAt(idx) == 36 // $
                ||objValue.getValue().charCodeAt(idx) == 37 // %
                ||objValue.getValue().charCodeAt(idx) == 94 // ^
                ||objValue.getValue().charCodeAt(idx) == 38 // &
                ||objValue.getValue().charCodeAt(idx) == 42 // *
                ||objValue.getValue().charCodeAt(idx) == 40 // (
                ||objValue.getValue().charCodeAt(idx) == 41 // )
                ||objValue.getValue().charCodeAt(idx) == 95 // _
                ||objValue.getValue().charCodeAt(idx) == 45 // -
                ||objValue.getValue().charCodeAt(idx) == 43 // +
                ||objValue.getValue().charCodeAt(idx) == 61 // =
                ||objValue.getValue().charCodeAt(idx) == 91 // [
                ||objValue.getValue().charCodeAt(idx) == 93 // ]
                ||objValue.getValue().charCodeAt(idx) == 123// {
                ||objValue.getValue().charCodeAt(idx) == 125// }
                ||objValue.getValue().charCodeAt(idx) == 124// |
                ||objValue.getValue().charCodeAt(idx) == 47 // \
                ||objValue.getValue().charCodeAt(idx) == 59 // ;
                ||objValue.getValue().charCodeAt(idx) == 58 // :
                ||objValue.getValue().charCodeAt(idx) == 39 // '
                ||objValue.getValue().charCodeAt(idx) == 34 // "
                ||objValue.getValue().charCodeAt(idx) == 44 // ,
                ||objValue.getValue().charCodeAt(idx) == 46 // .
                ||objValue.getValue().charCodeAt(idx) == 63 // ?
                ||objValue.getValue().charCodeAt(idx) == 92 // /
                ))
            {
                if (case4 != "true"){
                    case4 = "true";
                    val_chk++;
                }
                val_str_chk++;
            }
            if (val_str_chk == 0){
                var retrnMsg = objValue.getValue().charAt(idx)+"은/는 입력 불가한 문자입니다.";
                objValue.setValue("");
                return retrnMsg;
            }
            val_str_chk = 0;  //입력 허용 문자 비교값 재설정
        }
        if (val_chk < 3) //입력된 문자의 조합을 검증한다.
        {
            confirm_msg ="입력 하신 사용자등록번호는 ";
            if (case1 == "true"){
                confirm_msg += "[영대문자]";
            }
            if (case2== "true"){
                confirm_msg += "[영소문자]";
            }
            if (case3== "true"){
                confirm_msg += "[숫자]";
            }
            if (case4== "true"){
                confirm_msg += "[특수문자]";
            }
            confirm_msg += " 로만 구성되어 있습니다. \n  3가지 이상의 문자종류로 구성되어야 합니다."
            objValue.setValue("");
            return confirm_msg;
        }
    }
}

