/**
 * 함수명   : Pm50ComUtil.gfn_eraseInvalidZero
 * 함수설명 : 전달받은 파라미터의 유효하지 않은 숫자에서 zero (맨앞의 0들 자리수 1 이상일때) 제거된 값을 반환한다.
 * 파라메터 : {String} 변환대상 입력 문자열(날짜)
 * 			  {int} 소수점 유무
 * 리턴     : {String} 변환결과 문자열
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : yyyy = Pm50ComUtil.gfn_eraseInvalidZero(mm, 2);
 */
Pm50ComUtil.gfn_eraseInvalidZero = function(str, isDot) {
	var pre_str = '';// 정수부
	var post_str = '';// 소수부(소수부 있을때 채워짐)

	if (isDot) {// 소수점이 있다면, 정수부만
		var index = str.indexOf('.');
		pre_str = str.substring(0, index);
		post_str = str.substring(index);
		str = pre_str;
	}
};
	


/**
 * 함수명   : Pm50ComUtil.gfn_formatFillZeroByValue
 * 함수설명 : 전달받은 파라미터의 길이를 iLen으로 "0"으로 채워 맞춘 값을 반환한다.
 * 파라메터 : {String} 변환대상 입력 문자열(날짜)
 * 			  {int} 변환요청 문자열 len
 * 리턴     : {String} 변환결과 문자열
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : yyyy = Pm50ComUtil.gfn_formatFillZeroByValue(mm, 2);
 */
Pm50ComUtil.gfn_formatFillZeroByValue = function(sVal, iVal) {
	var sStr = sVal + "";

	for (var ii = sStr.length; ii < iVal; ii++) {
		sStr = "0" + sStr;
	}	
	return sStr;
};


/**
 * 함수명   : Pm50ComUtil.gfn_delComma
 * 함수설명 : 전달받은 파라미터 문자열의 ','문자를 제거한 문자를 반환한다.
 * 파라메터 : {String} 변환대상 문자열
 * 리턴     : {String} 변환결과 문자열
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_delComma(ibx_buld_stru_cont.getValue())
 */	
Pm50ComUtil.gfn_delComma = function(str) {
	if (str.length < 1) {
		return "";
	} else {
		var st = "";
		var sp = ",";
		for (var i = 0; i < str.length; i++) {
			if (sp.indexOf(str.substring(i, i + 1)) == -1) {
				st += str.substring(i, i + 1);
			}
		}
		return st;
	}
}


/**
 * 함수명   : Pm50ComUtil.gfn_addComma
 * 함수설명 : 전달받은 파라미터 문자열의 ','문자를 추가(화폐단위 및 실수에 자동으로 3자리 쉼표)한 문자를 반환한다.
 * 파라메터 : {String} 변환대상 문자열
 * 리턴     : {String} 변환결과 문자열
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_addComma(ibx_buld_stru_cont.getValue())
 */	
Pm50ComUtil.gfn_addComma = function(str) {
	var str = String(Pm50ComUtil.gfn_delComma(str));

	if (str.length < 1) {
		return "";
	} else {
		var tm = "";
		var ck = "";
		var tm1 = "";
		var tm2 = "";

		if (str.substring(0, 1) == "-") {
			tm = str.substring(1, str.length);
			ck = "Y";
		} else {
			tm = str;
			ck = "N";
		}

		// alert('tm='+tm);

		// 실수경우 . 을 기준으로 그 앞에만 comma 를 붙임
		var idx = 0;
		var isReal = false;// 실수여부
		for (i = 0; i < tm.length; i++) {
			if (tm.charAt(i) == '.') {
				idx = i;
				isReal = true;
				break;
			}
		}// end for
		if (isReal) {
			tm1 = tm.substring(0, idx);
			tm2 = tm.substring(idx + 1, tm.length);
			tm = tm1;
		}

		var st = "";
		var cm = ",";

		for (var i = tm.length, j = 0; i > 0; i--, j++) {

			if ((j % 3) == 2) {
				if (tm.length == j + 1) {
					st = tm.substring(i - 1, i) + st;
				} else {
					st = cm + tm.substring(i - 1, i) + st;
				}
			} else {
				st = tm.substring(i - 1, i) + st;
			}
		}

		if (ck == "Y") {
			st = "-" + st;
		}

		if (isReal) {// 실수경우
			st += "." + tm2;
		}

		obj = st;

	}
}	

