/**
 * 함수명   : Pm50ComUtil.gfn_removeSpace
 * 함수설명 : 전달받은 파라미터 문자열의 공백을 제거하고 반환한다.
 * 파라메터 : {String} 변환(공백 제거)대상 문자열
 * 리턴     : {String} 변환(공백 제거)결과 문자열
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_removeSpace(ibx_buld_stru_cont.getValue())
 */	
Pm50ComUtil.gfn_removeSpace = function(str) {		
	var len, index;
    while (true) {
         index = str.indexOf(" ");
         if (index == -1) break;
         len = str.length;
         str = str.substring(0, index) + str.substring((index+1),len);
    }
    return str;
};
			
	
