/**
 * 함수명   : Pm50ComUtil.gfn_today
 * 함수설명 : 전달받은 파라미터(날짜 문자열) 현재일 이후 일자인지 검증한다.
 * 파라메터 : {String} 검증대상 입력 문자열(날짜)
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : if( Pm50ComUtil.gfn_today(ibx_rgs_caus_date.getValue())!=true){
 * 					com.win.openMessagePopup("error", "egov.message.title.web.Pm50ComUtil.error", "pm50.message.error.web.Pm50ComUtil.0003", "등기원인일자");
 *  				return false;
 * 			  }
 */	
Pm50ComUtil.gfn_today = function(strDate){
	var today = new Date();
	var yyyy = today.getFullYear();
	var mm = today.getMonth() + 1;
	var dd = today.getDate();

	var chg_date = strDate.substr(0, 4) + strDate.substr(5, 2) + strDate.substr(8, 2);
	yyyy = Pm50ComUtil.gfn_formatFillZeroByValue(yyyy, 4);
	mm = Pm50ComUtil.gfn_formatFillZeroByValue(mm, 2);
	dd = Pm50ComUtil.gfn_formatFillZeroByValue(dd, 2);

	if (chg_date > yyyy + mm + dd) {
		return false;
	}

	return true;
}
	
	
/**
 * 함수명   : Pm50ComUtil.gfn_intFigure
 * 함수설명 : 전달받은 파라미터(실수)의 정수부 유효숫자 자리수 확인한다.
 * 파라메터 : {String} 검증대상 입력 실수
 *          : {int} 정수부 유효숫자 자리수
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : 
 */	
Pm50ComUtil.gfn_intFigure = function(iVal, size) {

	var minus = (iVal.charAt(0) == '-') ? '-' : '';
	var dot = ''; // 소수점

	var str = new String(Pm50ComUtil.gfn_delHyphen(iVal));
	var str_dot = '';// 소수점 이하 문자열
	str = Pm50ComUtil.gfn_delComma(str);

	var dot_index = 0;
	var int_str = '';// 정수부 숫자열
	var int_len = 0;// 정수부 유효숫자 자리 길이

	if ((str == '') || (str.length == 0)) {
		return true;
	}

	for (i = 0; i < str.length; i++) {
		if (!Pm50ComUtil.gfn_isInt(str.charAt(i))) {
			if (str.charAt(i) == '.') {
				dot_index = i;
				break;
			}
		}
	}// end for

	if (dot_index > 0) { // 소수점이 있다면
		int_str = str.substring(0, dot_index);
		str_dot = str.substring(dot_index + 1);
		dot = '.';
	} else if (dot_index == 0) {
		int_str = str;
	}

	int_len = int_str.length;

	if (int_len > size) {
		str = str.substring(0, size);
		obj = minus + str + dot + str_dot;
		return false;
	}

	return true;
}
	

/**
 * 함수명   : Pm50ComUtil.gfn_realFigure
 * 함수설명 : 전달받은 파라미터(실수)의 소수점이하 유효숫자 자리수 확인한다.
 * 파라메터 : {String} 검증대상 입력 실수
 *          : {int} 소수점이하 유효숫자 자리수
 * 리턴     : {boolean} 검증결과(true/false)
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : 
 */
Pm50ComUtil.gfn_realFigure = function(dVal, size) {
	var dot_position = dVal.indexOf('.');
	var str_before_dot = '';
	var dot = '';

	if (dot_position != -1) {
		str_before_dot = dVal.substring(0, dot_position);
	}

	var str = new String(Pm50ComUtil.gfn_delComma(dVal));
	var dot_index = 0;
	var dot_under_str = '';// 소수점이하 숫자열
	var dot_under_len = 0;// 소수점이하 숫자열의 길이

	if ((str == '') || (str.length == 0)) {
		return true;
	}

	for (i = 0; i < str.length; i++) {
		if (!Pm50ComUtil.gfn_isInt(str.charAt(i))) {
			if (str.charAt(i) == '.') {
				dot_index = i;
				break;
			}
		}
	}// end for

	if (dot_index > 0) {// 소수점이 있다면
		dot_under_str = str.substring(dot_index + 1);
		dot_under_len = dot_under_str.length;
		dot = '.';
		if (dot_under_len > size) {
			dot_under_str = dot_under_str.substring(0, size);
			obj = str_before_dot + dot + dot_under_str;

			return false;
		}
	}

	return true;
}


/**
 * 함수명   : Pm50ComUtil.gfn_fillZero
 * 함수설명 : 전달받은 파라미터(실수)의 실수의 정수부 .4 -> 0.4로 변환하여 반환한다.
 * 파라메터 : {String} 변환대상 입력 문자열(실수)
 * 리턴     : {String} 변환결과 문자열
 * 작성일   : 2022.05.01
 * 작성자   : 홍길동
 * @example : Pm50ComUtil.gfn_fillZero(lbx_amt.getValue())
 */		
Pm50ComUtil.gfn_fillZero = function(str) {
	var strObj = "";
	var dot = ''; // 소수점
	var str_dot = '';// 소수점 이하 문자열

	var dot_index = 0;
	var int_str = '';// 정수부 숫자열
	var int_len = 0;// 정수부 유효숫자 자리 길이

	str = new String(Pm50ComUtil.gfn_delHyphen(str));
	str = Pm50ComUtil.gfn_delComma(str);

	for (i = 0; i < str.length; i++) {
		if (!Pm50ComUtil.gfn_isInt(str.charAt(i))) {
			if (str.charAt(i) == '.') {

				dot_index = i;

				if (dot_index == 0) {// 소수점이 있다면
					int_str = 0;
					str_dot = str.substring(dot_index + 1);
					dot = '.';

					int_str = int_str + dot + str_dot;

					dot_index = 100;

				} else if (dot_index > 0) {// 소수점이 있다면
					int_str = str.substring(0, dot_index);
					str_dot = str.substring(dot_index + 1);
					dot = '.';

					int_str = int_str + dot + str_dot;
				}
			}
		}
	}// end for

	if (dot_index == 0) {// 소수점이 없다
		int_str = str;
	}

	return int_str;
}

Pm50ComUtil.getDateStr = function(myDate){
    var year = myDate.getFullYear();
    var month = (myDate.getMonth() + 1);
    var day = myDate.getDate();
    
    month = (month < 10) ? "0" + String(month) : month;
    day = (day < 10) ? "0" + String(day) : day;
    
    return ( year + '-' + month + '-' + day );
}

Pm50ComUtil.today = function(){
    var d = new Date();
    return Pm50ComUtil.getDateStr(d);
}

Pm50ComUtil.lastWeek = function(){
    var d = new Date();
    var dayOfMonth = d.getDate();
    d.setDate(dayOfMonth - 7);
    return Pm50ComUtil.getDateStr(d);
}

Pm50ComUtil.last2Month = function(){
    var d = new Date();
    var monthOfYear = d.getMonth();
    d.setMonth(monthOfYear - 2);
    return Pm50ComUtil.getDateStr(d);
}

Pm50ComUtil.last3Month = function(){
    var d = new Date();
    var monthOfYear = d.getMonth();
    d.setMonth(monthOfYear - 3);
    
    var dayOfMonth = d.getDate();
    d.setDate(dayOfMonth + 1);
    
    return Pm50ComUtil.getDateStr(d);
}

Pm50ComUtil.lastMonth = function(){
    var d = new Date();
    var monthOfYear = d.getMonth();
    d.setMonth(monthOfYear - 1);
    return Pm50ComUtil.getDateStr(d);
}

Pm50ComUtil.gfn_formattedText = function(pInstr, pInformat) {
	var rStr = "";
	
	var i = 0;
	for (var j = 0; i < pInformat.length; ++i) {
		if (pInformat.charAt(i) == '#') {
			rStr += pInstr.charAt(j);
			++j;
		} else {
			rStr += pInformat.charAt(i);
		}
	}
	return rStr;
}

/**
 * 함수명   : Pm50ComUtil.gfn_viewPdf
 * 함수설명 : PDF 보기
 * 파라메터 : N/A
 * 리턴     : N/A
 * 작성일   : 2022.10.19
 * 작성자   : 황경진
 */
Pm50ComUtil.gfn_viewPdf = function() {
	var arg = arguments[0];
	if (!arg) {
		return;
	}
	
	var paramData = {};
	paramData[Pr10ComBase.FILE_ORG_NAME] = arg.pdfName;
	paramData[Pr10ComBase.FILE_DOWN_TYPE] = Pr10ComBase.FILE_DOWN_TYPE_FILE;
	paramData[Pr10ComBase.FILE_PATH_CLS] = Pr10ComBase.FILE_PATH_CLS_EDMS_TEMP;
	
	var url = Pr10ComBase.gfn_getCryptedIdUri("/biz/Pm50ComFileUpDownCtrl/downloadFile.do");

	var xhr = new XMLHttpRequest();
	xhr.open("POST", url, true);
	xhr.setRequestHeader('Content-Type', 'application/json;charset=UTF-8');
	xhr.responseType = "blob";
	xhr.overrideMimeType('application/pdf');
	xhr.onreadystatechange = function() {
		if (xhr.readyState == XMLHttpRequest.DONE) {
			if (xhr.status == 200) {
				if (navigator.msSaveOrOpenBlob) {
					navigator.msSaveOrOpenBlob(xhr.response, arg.pdfName);
				} else {
					var blobUrl = URL.createObjectURL(xhr.response);
					arg.target.setSrc(blobUrl);
					URL.revokeObjectURL(blobUrl);
				}
				if (arg.succCallback) {
					arg.succCallback();
				}
			} else {
				if (arg.failCallback) {
					arg.failCallback(xhr);
				}
			}
		}
	};
	xhr.send(JSON.stringify(paramData));
}

