 * 함수설명 : 단일 or 다중 validation을 위한 분기 함수 
 * 파라미터 : validation구분, 대상컴포넌트, 부모그룹컴포넌트, 커스텀오류메시지
 * 리턴     : 성공여부(true/false)
 * 작성일   : 2022.06.02
 * 작성자   : 손힘찬
 */
Pc10ComValidate.gfn_cmmnValidateData = function(validateCls, comp, parentGrp, errMsg, subsComp) {
	if(typeof validateCls == 'object'){
		for(var i = 0 ; i < validateCls.length ; i++){
			var rtnObj = Pc10ComValidate.gfn_execValidateData(validateCls[i], comp, subsComp);
			if(!rtnObj.result){
				Pc10ComValidate.gfn_showValidateMsg(comp, rtnObj, parentGrp, (com.util.isNotEmpty(errMsg) ? errMsg[i] : ''));
				return false; 
			}
		}
	}else if(typeof validateCls == 'string'){
		var rtnObj = Pc10ComValidate.gfn_execValidateData(validateCls, comp, subsComp);
		if(!rtnObj.result){
			Pc10ComValidate.gfn_showValidateMsg(comp, rtnObj, parentGrp, (com.util.isNotEmpty(errMsg) ? errMsg : ''));
			return false;
		}
	}
	return true;
};

/**
 * 함수명   : Pc10ComValidate.gfn_execValidateData
 * 함수설명 : 단일 or 다중 validation을 위한 분기 함수 
 * 파라미터 : validation구분, 대상컴포넌트
 * 리턴     : 결과객체(성공여부, 메시지정보)
 * 작성일   : 2022.06.08
 * 작성자   : 손힘찬
 */
Pc10ComValidate.gfn_execValidateData = function(validateCls, comp, subsComp) {

	var epos = validateCls.search("=");
	var command = "";
	var cmdValue = "";

	var value = comp.getValue();

	if (epos >= 0) {
		command = validateCls.substring(0, epos);
		cmdValue = validateCls.substr(epos + 1);
	} else {
		command = validateCls;
	}

	var spaErrObj = com.comp.getComponent(comp.getID()+'_error');

	if(spaErrObj != null) {
		comp.removeClass('reqbox');
		spaErrObj.remove();
	}

	var rtnObj = {'result' : true};

	switch (command) {

	case "req":
	case "required": {
		value = value.trim();

		if (value.length == 0) {
			rtnObj.result = false;
			rtnObj.msgCd = '0001';
		}// if
		break;
	}// case required
	case "maxlen":
	case "maxlength": {
		if (parseInt(Pc10ComValidate.gfn_getByte(value)) > parseInt(cmdValue)) {
			rtnObj.result = false;
			rtnObj.msgCd = '0002';
			rtnObj.msgArgs = cmdValue;
		}// if
		break;
	}// case maxlen
	case "minlength":
	case "minlen": {
		if (parseInt(Pc10ComValidate.gfn_getByte(value)) < parseInt(cmdValue)) {
			rtnObj.result = false;
			rtnObj.msgCd = '0003';
			rtnObj.msgArgs = cmdValue;
		}// if
		break;
	}// case minlen
	case "alnum":
	case "alphanumeric": {
		var charpos = value.search("[^A-Za-z0-9]");
		if (value.length > 0 && charpos >= 0) {
			rtnObj.result = false;
			rtnObj.msgCd = '0007';
		}// if
		break;
	}// case alphanumeric
	case "num":
	case "numeric": {
		var charpos = value.search("[^0-9]");
		if (value.length > 0 && charpos >= 0) {
			rtnObj.result = false;
			rtnObj.msgCd = '0008';
		}// if
		break;
	}// numeric
	case "numericdot": {
		var charpos = value.search("[^0-9.]");
		if (value.length > 0 && charpos >= 0) {
			rtnObj.result = false;
			rtnObj.msgCd = '0008';
		}// if
		break;
	}// numericdot
	case "numericdash": {
		var charpos = value.search("[^0-9-]");
		if (value.length > 0 && charpos >= 0) {
			rtnObj.result = false;
			rtnObj.msgCd = '0008';
		}// if
		break;
	}// numeric
	case "alphabetic":
	case "alpha": {
		var charpos = value.search("[^A-Za-z]");
		if (value.length > 0 && charpos >= 0) {
			rtnObj.result = false;
			rtnObj.msgCd = '0006';
		}// if
		break;
	}// alpha
	case "alnumhyphen": {
		var charpos = value.search("[^A-Za-z0-9\-_]");
		if (value.length > 0 && charpos >= 0) {
			rtnObj.result = false;
			rtnObj.msgCd = '0009';
		}// if
		break;
	}
	case "email": {
		if (!Pc10ComValidate.gfn_checkEmail(value)) {
			rtnObj.result = false;
			rtnObj.msgCd = '0013';
		}// if
		break;
	}// case email
	case "lt":
	case "lessthan": {
		if (isNaN(value)) {
			rtnObj.result = false;
			rtnObj.msgCd = '0008';
			return false;
		} else if (parseInt(value) >= parseInt(cmdValue)) {
			//errMsg = f_makemsg(SECOM006, value + "," + cmdValue); // 입력된
			rtnObj.result = false;
			rtnObj.msgCd = '0004';
			rtnObj.msgArgs = cmdValue;
		}// if
		break;
	}// case lessthan
	case "gt":
	case "greaterthan": {
		if (isNaN(value)) {
			//alert(title + SECOM010); // numeric 형식이 아닙니다.pc10.message.info.web.com.0008
			rtnObj.result = false;
			rtnObj.msgCd = '0008';
		}// if

		if (parseInt(value) <= parseInt(cmdValue)) {
				//errMsg = f_makemsg(SECOM007, value + "," + cmdValue); // 입력된pc10.message.info.web.com.0005
			rtnObj.result = false;
			rtnObj.msgCd = '0005';
			rtnObj.msgArgs = cmdValue;
		}// if
		break;
	}// case greaterthan
	case "regexp": {
		if (value.length > 0) {
			if (!value.match(cmdValue)) {
					//errMsg = f_makemsg(SECOM016, cmdValue); // Regularpc10.message.info.web.com.0014
				rtnObj.msgCd = '0014';
			}// if
		}
		break;
	}// case regexp
	case "dontselect": {
		if (value == null) {// TODO 확인해야함
			//alert(title + SECOM013); // 선택된 목록이 없습니다.pc10.message.info.web.com.0011

			rtnObj.result = false;
			rtnObj.msgCd = '0011';
