	             || ( value.charCodeAt(idx)==45 )  // 하이픈
	             ) ){
  	            // [등록번호] 정해진 문자외에는 사용하실 수 없습니다.\n 정해진 문자 : 숫자, [-]
				rtnObj.result = false;
				rtnObj.msgCd = '0336';
	        }
	    }
		break;
	// 2026.09.03 해외주소입력 체크 메시지 추가 2026-W00448
	case "frnAddr" :
		if (Pc10ComValidate.gfn_includeWromChar(value)) {
			// 로마자 또는 한자가 입력되었습니다.<br>입력된 문자는 로마자란에 입력되어야 합니다.
			rtnObj.result = false;
			rtnObj.msgCd = '0382';
		}
		break;	
	}// switch


	if (Pc10ComValidate.focusFlag && !rtnObj.result) {
		if (comp.getDisabled() && Pc10ComBase.gfn_isNotEmpty(subsComp)) {
			subsComp.focus();
			Pc10ComValidate.focusComp = subsComp;
		} else {
			comp.focus();
			Pc10ComValidate.focusComp = comp;
		}
		Pc10ComValidate.focusFlag = false;
	}

	return rtnObj;
}

/**
 * 함수명   : Pc10ComValidate.gfn_getByte
 * 함수설명 : string 값을 byte length를 추출한다.
 * 파라미터 : 추출대상값
 * 리턴     : byte길이
 * 작성일   : 2022.06.08
 * 작성자   : 손힘찬
 */
Pc10ComValidate.gfn_getByte = function(param) {
	var len = 0;

	for (var i = 0; i < param.length; i++, len++) {
		if ((param.charCodeAt(i) < 0) || (param.charCodeAt(i) > 127))
			len++; // add extra length
	}

	return len;
}

