/**
 * 함수명   : Pc10ComValidate.gfn_cmmnEnrNoChk
 * 함수설명 : 등기할사항 임원, 지배인의 주민등록번호 validate check를 위한 함수이다.
 * 파라미터 : 등록번호구분, 등록구분(주민등록번호/생년월일), 주민등록번호 앞자리 컴포넌트, 주민등록번호 뒷자리 컴포넌트
 *            , 생년월일 컴포넌트, 부모그룹ID
 * 리턴     : 성공여부(true/false)
 * 작성일   : 2022.07.14
 * 작성자   : 박기윤
 */
Pc10ComValidate.gfn_checkCmmnEnrNo = function(enrNoCls, enrCls , compFdgtREnrNo, compLdgtREnrNo, compBirth, parentGrp){
    //주민등록번호 체크로직 시작
    var enrNoCls = enrNoCls; //등록번호 구분코드
    var rEnrNo = compFdgtREnrNo.getValue() + compLdgtREnrNo.getValue(); //주민등록번호
    var birth; //법인등록번호, 등록번호, 생년월일
    var enrNo;
    var comp;

    if(!Pc10ComBase.gfn_isEmpty(compBirth)) {
    	birth = compBirth.getValue();
    	comp = [compFdgtREnrNo, compLdgtREnrNo, compBirth];
    } else {
    	comp = [compFdgtREnrNo, compLdgtREnrNo];
    }

    // error 클래스 및 컴포넌트 삭제
    for(var i = 0; i < comp.length; i++){
        var enrErrObj= com.comp.getComponent(comp[i].getID()+'_error');

        if(enrErrObj != null) {
        	comp[i].removeClass('reqbox');
            enrErrObj.remove();
        }
    }

    //재외국민, 외국인이 생년월일을 입력한 경우
    if((enrNoCls == "12912" && enrCls == "birth") || (enrNoCls == "12913" && enrCls == "birth")){
            if(!Pc10ComValidate.gfn_chkBirthDay(birth)){
                Pc10ComValidate.gfn_showValidateMsg(compBirth , {'msgCd' :'0043', 'msgArgs' : ''}, parentGrp);
            	if (Pc10ComValidate.focusFlag) {
            		compBirth.focus();
            		Pc10ComValidate.focusFlag = false;
            		Pc10ComValidate.focusComp = compBirth;
            	}
	            return false;
            }else{
                var tmpBirthDay = Pc10ComValidate.gfn_makeSpace(birth);
	                if( birth != tmpBirthDay){
	                	/*
                        var mesOption = {
                        	msgType     : 'info',
                        	msgTitle    : 'egov.message.title.web.com.info',
                        	msgCode     : 'pc10.message.info.web.com.0044',
                        	msgArg      : birth + '^' + tmpBirthDay
                        };
	                    com.message.openMessage(mesOption, '');
	                	 */
                    compBirth.setValue(tmpBirthDay);
                    }
	            return true;
            }
    //주민등록번호를 입력한 경우
    }else{  
            if(com.util.isEmpty(rEnrNo)){
                enrNo = birth;
            }else{
                enrNo = rEnrNo;
            }
            if(!Pc10ComValidate.gfn_checkEnrNo(enrNoCls, enrNo)){
                Pc10ComValidate.gfn_showValidateMsg([compFdgtREnrNo, compLdgtREnrNo] , {'msgCd' :'0042', 'msgArgs' : ''}, parentGrp);
            	if (Pc10ComValidate.focusFlag) {
            		compFdgtREnrNo.focus();
            		Pc10ComValidate.focusFlag = false;
            		Pc10ComValidate.focusComp = compFdgtREnrNo;
            	}
                return false;
            }
    }
    return true;
}



Pc10ComValidate.gfn_checkCorpName = function(corpCls, conmComp, corpName, isAtpcl, parentGrp, selConmClsComp, smplCoYn){

