Pc10ComValidate.gfn_checkWromCorpName = function(comp, corpClsCd, parentGrp) {
	var wromConm = comp.getValue();
	var convertWromConm = "";
	var isWrom = false;
	var isChin = false;

	if (corpClsCd == "46" || corpClsCd == "53") { // 법무법인, 법무사법인 일경우로마자 괄호허용
	    if (!Pc10ComValidate.gfn_cmmnValidateData(['inchar=corp13', 'maxlen=120'], comp, parentGrp)) {
	        return false;
	    }
	} else {
	    if (!Pc10ComValidate.gfn_cmmnValidateData(['inchar=corp11', 'maxlen=120'], comp, parentGrp)) {
	        return false;
	    }
	}

	// 로마자의 처음과 끝문자가 특수문자인지 체크...
	if (wromConm != "") {
		var sChar = "&,.-·";
		var eChar = "&,-·'";
		if (sChar.indexOf(wromConm.charAt(0)) != -1
				|| eChar.indexOf(wromConm.charAt(wromConm.length - 1)) != -1) {
			Pc10ComValidate.gfn_showValidateMsg(comp, {'msgCd' :'0046', 'msgArgs' : ''}, parentGrp);
			if (Pc10ComValidate.focusFlag) {
				comp.focus();
				Pc10ComValidate.focusFlag = false;
				Pc10ComValidate.focusComp = comp;
			}
			return false;
		}
	}

	for (var idx = 0; idx < wromConm.length; idx++) {
		if (idx != 0) {
			if (!(wromConm.charCodeAt(idx) == 32 && wromConm
					.charCodeAt(idx - 1) == 32))
				convertWromConm = convertWromConm + wromConm.charAt(idx);
		} else {
			convertWromConm = convertWromConm + wromConm.charAt(idx);
		}

		if (((wromConm.charCodeAt(idx) >= 65) && (wromConm
				.charCodeAt(idx) <= 90)) // 영문(대문자)
				|| ((wromConm.charCodeAt(idx) >= 97) && (wromConm
						.charCodeAt(idx) <= 122))) {// 영문(소문자)
			isWrom = true;
		}
		if (((wromConm.charCodeAt(idx) >= 19968) && (wromConm
				.charCodeAt(idx) <= 40869)) // 한자
				|| ((wromConm.charCodeAt(idx) >= 63744) && (wromConm
						.charCodeAt(idx) <= 64045))) { // 한자2
			isChin = true;
		}
	}

	if (isWrom == true && isChin == true) {
		Pc10ComValidate.gfn_showValidateMsg(comp, {'msgCd' :'0047', 'msgArgs' : ''}, parentGrp);
		if (Pc10ComValidate.focusFlag) {
			comp.focus();
			Pc10ComValidate.focusFlag = false;
			Pc10ComValidate.focusComp = comp;
		}
		return false;
	}

	comp.setValue(convertWromConm);

	return true;
}

/**
 * 함수명   : Pc10ComValidate.gfn_compareDate(AS-IS : f_curdateCB())
 * 함수설명 : 일자가 현재일을 기준으로 미래 60일까지만 가능하도록 검증한다.
 * 파라미터 : 대상컴포넌트(일자), 부모그룹
 * 리턴     : N/A
 * 작성일   : 2022.07.18
 * 작성자   : 하영준
 */
Pc10ComValidate.gfn_compareDate = function(comp, parentGrp) {
	var objDate     = comp.getValue();
    var extendDay   = 60;    //현재일 기준으로 미래 60일까지 가능하도록 변수를 세팅한다.
    var diffDate    = Pc10ComValidate.gfn_calcDateDiff(objDate);
    var messageCode = "";
    var rtn         = true;

    if (diffDate > extendDay) {
    	messageCode = 'pc10.message.info.web.com.1064';
    	Pc10ComValidate.gfn_callErrMsg(comp, parentGrp, messageCode);
		if (Pc10ComValidate.focusFlag) {
			comp.focus();
			Pc10ComValidate.focusFlag = false;
			Pc10ComValidate.focusComp = comp;
		}
        rtn = false;
    }

    return rtn;
};

/**
 * 함수명   : Pc10ComValidate.gfn_checkDate
 * 함수설명 : 일자가 현재일을 기준으로 미래일자를 입력했는지 체크한다.
 * 파라미터 : 대상컴포넌트(일자), 부모그룹
 * 리턴     : N/A
 * 작성일   : 2022.08.05
 * 작성자   : 하영준
 */
Pc10ComValidate.gfn_checkDate = function(comp, parentGrp) {
	var objDate     = comp.getValue();
    var extendDay   = 60;    //현재일 기준으로 미래 60일까지 가능하도록 변수를 세팅한다.
    var diffDate    = Pc10ComValidate.gfn_calcDateDiff(objDate);
    var rtn         = true;

    if (diffDate > 0 && diffDate < (extendDay + 1)) {
		if (Pc10ComValidate.focusFlag) {
			comp.focus();
			Pc10ComValidate.focusFlag = false;
			Pc10ComValidate.focusComp = comp;
		}
        rtn = false;
    }

    return rtn;
}

/**
 * 함수명   : Pc10ComValidate.gfn_calcDateDiff
 * 함수설명 : 현재일 기준으로 입력한 일자와의 차이를 계산한다.
 * 파라미터 : 대상컴포넌트(일자)
 * 리턴     : N/A
 * 작성일   : 2022.08.05
 * 작성자   : 하영준
 */
Pc10ComValidate.gfn_calcDateDiff = function(objDate) {
    var todayDate   = new Date();
    var compareDate = new Date(objDate.substring(0,4), objDate.substring(4,6)-1, objDate.substring(6,8));
    var diffDate    = Math.ceil((compareDate - todayDate) / (24*60*60*1000));

    return diffDate;
};

/**
 * 함수명   : Pc10ComValidate.gfn_chkTabKey(AS-IS : f_ChkTab())
 * 함수설명 : 탭(Tab)이 입력된 경우를 확인한다.
