 */
Pc10ComValidate.gfn_chkTabKey = function(objValue){
    var rtn = false;
    for (var idx=0; idx < objValue.length; idx++) {
        if ( objValue.charCodeAt(idx) == 9 ) {  // tab입력체크
            rtn = true;
            break;
        }
    }
    return rtn;
};

