 * 작성일   : 2022.07.18
 * 작성자   : 하영준
 */
Pc10ComValidate.gfn_replaceTabKey = function(objValue) {
    for (var idx=0; idx < objValue.length; idx++) {
        if (objValue.charCodeAt(idx) == 9 ) {  // tab입력체크
           objValue = objValue.replace( /\t/g," ");
