/**
 * 함수명   : Pc10ComValidate.gfn_checkTelNo
 * 함수설명 : 전화번호를 검증한다.
 * 파라미터 : msgCd, msgArg
 * 리턴     : N/A
 * 작성일   : 2022.12.06
 * 작성자   : 박기윤
 */
Pc10ComValidate.gfn_checkTelNo = function(value) {
	var strRegTel = /^([0-9]{2}|[0-9]{3}|[0-9]{4})-[0-9]{3,4}-[0-9]{4}$/; //0000-000-0000, 0000-0000-0000 형식으로만 작성가능
	if(Pc10ComBase.gfn_isNotEmpty(value)){
		var tmpValue = value.replace(/ /gi, ""); //공백제거
		if(!strRegTel.test(tmpValue)) {
				return false;
			}else{
				return true;
			}
		}	
	return true;
};

