/**
 * 함수명   : Pc10ComValidate.gfn_includeWromChar
 * 함수설명 : 영문자가 포함되어있는지 확인한다.
 * 파라미터 : 
 * 리턴     : true/false
 * 작성일   : 2024.11.27
 * 작성자   : 박기윤
 */
Pc10ComValidate.gfn_includeWromChar = function(value) {
    var wromFrgsConm = value;
    var chgWromFrgsConm = "";
    var romaYN = false;
    var hanjaYN = false;

    for (var idx=0 ; idx < wromFrgsConm.length ; idx++) {
        if( idx != 0 ){
            if( !(wromFrgsConm.charCodeAt(idx)==32 && wromFrgsConm.charCodeAt(idx-1)==32) )
                chgWromFrgsConm = chgWromFrgsConm + wromFrgsConm.charAt(idx);
        }else{
            chgWromFrgsConm = chgWromFrgsConm + wromFrgsConm.charAt(idx);
        }

        if ( ( (wromFrgsConm.charCodeAt(idx)>=65) && (wromFrgsConm.charCodeAt(idx)<=90) )       // 영문(대문자)
            || ( (wromFrgsConm.charCodeAt(idx)>=97) && (wromFrgsConm.charCodeAt(idx)<=122)) ) {// 영문(소문자)
            romaYN = true;
        }
        if ( ( (wromFrgsConm.charCodeAt(idx)>=19968) && (wromFrgsConm.charCodeAt(idx)<=40869)  )     // 한자
            || ( (wromFrgsConm.charCodeAt(idx)>=63744) && (wromFrgsConm.charCodeAt(idx)<=64045)) ) { // 한자2
            hanjaYN = true;
        }
    }

    return romaYN || hanjaYN;
}

