var Pc30ComBase = {};

/**
 * 함수명   : Pc30ComBase.gfn_chkDate
 * 함수설명 : 날자의 유효성을 체크한다.
 * 파라메터 : 체크할 값
 * 리턴     : 체크결과(true/false)
 * 작성일   : 2022.06.27
 * 작성자   : 박상규
 */
Pc30ComBase.gfn_chkdate = function(date) {

    var iYear = date.substr(0,4);
    var iMonth = date.substr(4,2);
    var iDay = date.substr(6,2);    
    var monthArr = new Array(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31);
    
    if( iMonth == 2 ) {
        if ( ( (iYear % 4 == 0) && (iYear % 100 != 0) ) || (iYear % 400 == 0) ) {
            monthArr[1] = "29";
        }
    }
        
    if (date.length != 8) {    	
        return false;
    }
    
    if( iYear < 9999 && iYear > 0 && iMonth <= 12 && iMonth > 0 && iDay <= monthArr[iMonth-1] && iDay > 0 ) {
        return true;
    }
	
};

