/**
 * 함수명 	: Pc30ComBase.createDataMapBind
 * 함수설명	: dataMap을 생성 후 컴포넌트와  바인딩한다.
 * 파라미터	: dcId : dataMap 아이디
 *			  initData : dataMap 생성 정보
 *			   - 컬럼, 데이터, 바이딩 컴포넌트
 * 리턴		: dataMap
 * 작성일 	: 2023.02.06
 * 작성자 	: 박상규
 * 예시	 	: API : Pc30ComBase.createDataMapBind
 */
Pc30ComBase.createDataMapBind = function(dcId, initData) {
	
	var colInfo	= [];
	var mapData	= {};
	
	// dataMap 생성 
	for (var item in initData) {
		colInfo.push({id : item});
		mapData[item]	= initData[item][0];
	}
	var dataMap	= com.data.createDataMap(dcId, colInfo, mapData);
	
	// 컴포넌트 바인딩.
	for (var item in initData) {
		if (initData[item].length == 2) {
			initData[item][1].setRef('data:' + dcId + '.' + item);
		}
	}
	
	return dataMap;
};

/**
 * 함수명 	: Pc30ComBase.createDataList
 * 함수설명	: dataList을 생성한다.
 * 파라미터	: dcId : dataList 아이디
 *			  colInfo : 컬럼정보
 *			  initData : 초기 데이터
 * 리턴		: dataList
 * 작성일 	: 2023.02.06
 * 작성자 	: 박상규
 * 예시	 	: API : Pc30ComBase.createDataList
 */
Pc30ComBase.createDataList = function(dcId, colInfo, initData) {
	
    try {
    	var compObj		= com.comp.getComponent(dcId);
    	var isCreate	= true;
    	var colOld		= '';
    	var colNew		= '';
    	
    	for (var i = 0 ; i < colInfo.length ; i ++) {
        	colInfo[i].name	= colInfo[i].name || colInfo[i].id;
    		colInfo[i].type	= colInfo[i].type || 'text';
    		
    		colNew	+= (i == 0) ? colInfo[i].id : ',' + colInfo[i].id;
        }
    	
    	if (com.util.isNotEmpty(compObj)) {
    		colOld	= compObj.cellIdList.join(',');
    		
    		if (colOld == colNew) {
    			isCreate	= false;
    		} else {
    			$p.data.remove(dcId);
    		}
    	}

    	if (isCreate) {
	    	var dataListInfo = {
	            id 		: dcId,
	            type 	: "dataList",
	            option 	: {
	                "baseNode" 			: "list",
	                "repeatNode"		: "map",
	                "saveRemovedData" 	: "true",
	            },
	            columnInfo : colInfo
	        };
	
	        $p.data.create(dataListInfo);
    	} else {
        	compObj.removeAll();
       }
        
        compObj	= com.comp.getComponent(dcId);
    	
        // dataMap 초기 데이터 설정
        if (initData) {
        	compObj.insertJSON(0, initData);
        	compObj.initRowStatus();
        }
        
        return compObj;
    } catch (ex) {
        console.error(ex);
    }
};

