/**
 * 함수명   : Pc30ComBase.gfn_setAutoPopupSize
 * 함수설명 : 선택한 요소의 변경을 감지하여 팝업사이즈를 자동 변경한다.
 * 파라메터 : popupObj : 공통함수에서 리턴한 팝업 정보 (resultType : ‘POPUP’)
 *			   - com.win.getPopup, com.win.searchPopup, com.win.searchPathPopup 함수를 이용해 popupObj 조회
 * 리턴     : N/A
 * 작성일   : 2022.11.04
 * 작성자   : 박상규
 */
Pc30ComBase.gfn_setAutoPopupSize = function(popupObj) {
	var MAX_HEIGHT = 820;
	
    try {
    	var element = document.querySelector('#'+ popupObj.id)
    						  .querySelector('div.w2group.popup-body > div.w2group.popup-cont');
    	
    	var scrollElement = document.querySelector('#'+ popupObj.id)
		  			 		        .querySelector('div.w2group.popup-body');
    	
        var popupWidth   = popupObj.windowInfo.defaultWidth.replace("px","");
        
        new ResizeObserver(function() {
        					   scrollElement.style.overflow = 'hidden';
        					   var popupHeight = element.offsetHeight + 200;
        					   
        					   // 스크롤 생성 기준 (max height 의존)
        					   if(element.offsetHeight > 644) {
        						   scrollElement.style.overflow = 'auto';
        					   }
        					   // 팝업 max height 제한
        					   if(popupHeight > MAX_HEIGHT) {
        						   popupHeight = MAX_HEIGHT;
        					   }
                               com.win.setPopupResizeTo(popupObj, popupWidth, popupHeight);
                           }).observe(element);		    
	} catch(e) {
		// 브라우저의 ResizeObserver 지원 여부 확인
	    console.log("Browser version error");
	}	
};

/**
 * 함수명   : Pc30ComBase.gfn_isEmpty
 * 함수설명 : 빈값체크 함수
 * 파라미터 : 체크할 값
 * 리턴     : 체크결과(true/false)
 * 작성일   : 2022.05.17
 * 작성자   : 박상규
 */
Pc30ComBase.gfn_isEmpty = function(value) {
	// 기본 체크
	if (com.util.isEmpty(value) == true) {
		return true;
	}
	// 객체 체크
	if (typeof value == "object") {
		// Array
		if (com.util.isArray(value)) {
			if (value.length == 0) {
				return true;
			}
		// Object
		} else if (value.constructor === Object && Object.keys(value).length === 0) {
			return true;
		}
	}
	return false;
};

