 * 작성일   : 2022.05.17
 * 작성자   : 박상규
 */
Pc30ComBase.gfn_isNotEmpty = function(value) {
	return !Pc30ComBase.gfn_isEmpty(value);
};

/**
 * 함수명   : Pc30ComBase
 * 함수설명 : DataList내 특정컬럼의 value를 비교해서 일치시 rowIndex 리턴하는 함수
 * 파라미터 : DataList(찾을 datalist), ArrayColumn(비교할 컬럼-[col1, col2]), ArrayValue(비교값 -[a,b] )
 * 리턴     : array(rowIndex)
 * 작성일   : 2023.05.19
 * 작성자   : 박상규
 */
Pc30ComBase.getCellValueRowIndex = function(pDataList, pArrColumn, pArrayValue) {
 
	
    var iFlagCnt; //비교결과 갯수
    var rtnIndex = []; // 리턴 rowIndex
    
    var arrColumn = pArrColumn; //비교대상 컬럼
    var arrVal = pArrayValue; //비교대상 value
    
    var arrColumnLength = arrColumn.length; //비교대상 컬럼 갯수
    var arrTemp = new Array(arrColumnLength); //비교결과 갯수 
    
    
    for(var i=0; i<pDataList.getTotalRow(); i++){
	    for(var j=0; j<arrColumnLength; j++){
		    var strTemp = pDataList.getCellData(i, arrColumn[j]);
		    if(arrVal[j] == strTemp){
			    arrTemp[j] = true;
			}else{
				arrTemp[j] = false;
			}
		}
		
		iFlagCnt = 0;
		for(var j=0; j<arrColumnLength; j++){
            if(arrTemp[j] == true){
                iFlagCnt++;
            }
        }
        
        if(iFlagCnt == arrColumnLength){
            rtnIndex.push(i);
        }
    }
     
    return rtnIndex;
     
 };
 
