  /**
   * 함수명   : Pc30ComBase.gfn_getMsgOption
   * 함수설명 : 메시지 옵션을 가져온다.
   * 파라메터 : type(메시지 유형), title(메시지 제목), code(메시지 코드), arg(메시지 인자)
   * 리턴     : mesOption(메시지 옵션)
   * 작성일   : 2022.12.07
   * 작성자   : 박상규
   */ 
  Pc30ComBase.gfn_getMsgOption = function(type, title, code, arg) {
  	if (type === 'error' || type === 'caution' || type === 'complete') {
  		title = 'egov.message.title.web.com.' + type;
  	} else {
  		title = 'egov.message.title.web.com.info';
  	}
  	
  	var mesOption = {
  		msgType     : type,
  		msgTitle    : title,
          msgCode     : code,
          msgArg      : arg
  	};
  	
  	return mesOption;
  }

  /**
   * 함수명   : Pc30ComBase.gfn_getByte
   * 함수설명 : string 값을 byte length를 추출한다.
   * 파라미터 : 추출대상값
   * 리턴     : byte길이
   * 작성일   : 2022.06.08
   * 작성자   : 박상규
   */
  Pc30ComBase.gfn_getByte = function(param) {
  	var len = 0;

  	for (var i = 0; i < param.length; i++, len++) {
  		if ((param.charCodeAt(i) < 0) || (param.charCodeAt(i) > 127))
  			len++; // add extra length
  	}

  	return len;
  }

