  /**
   * 함수명   : Pc30ComBase.gfn_setMask
   * 함수설명 : 데이터를 마스킹 처리한다.
   * 파라메터 : val, st, ed
   * 리턴     : 
   * 작성일   : 2022.12.20
   * 작성자   : 박상규
   */
  Pc30ComBase.gfn_setMask = function(val, st, ed) {
  	var maskVal = '';
  	var length = val.length;
  	
  	if (Pc30ComBase.gfn_isEmpty(val)) {
  		return '';
  	}	
  	
  	if (Pc30ComBase.gfn_isEmpty(st)) {
  		st = 0;
  	}
  	
  	if (Pc30ComBase.gfn_isEmpty(ed)) {
  		ed = length;
  	}

  	for (var i = 0; i < length; i++) {
  		if (st <= i && i <= ed) {
  			maskVal += '*';
  		} else {
  			maskVal += val.charAt(i);
  		}
  	}
  	return maskVal;
  }

