  /**
   * 함수명   : Pc30ComBase.gfn_viewFile
   * 함수설명 : xml로 생성된 문서를 iframe 영역에 보여준다.
   * 파라미터 : iframeID, xml파일명, xml파일경로, xsl파일명, xsl파일경로
   * 리턴     : 
   * 작성일   : 2023.07.04
   * 작성자   : 박상규
   */
  Pc30ComBase.gfn_viewFile = function(ifmComp, xmlName, xmlPath, xslName, xslPath) {
  	var isXmlDown = true;
  	var xmlDoc;

      com.data.createDataMapSimple('dma_file_info', {'file_name' : '', 'file_path' : ''});
      
      var options = {
          id              : 'sbm_Pc30R0RgcsdWrtCsCtrl_downloadFile',         // sbm_Pc30R0RgcsdWrtCsCtrl_downloadFile  // submission 객체의 ID. 통신 모듈 실행 시 필요.
          ref             : 'data:json,{"id":"dma_file_info", "key":"websquare_param"}', // 서버로 보낼(request) DataCollection의 조건 표현식.(조건에 때라 표현식이 복잡하다) 또는 Instance Data의 XPath.
          target          : '',         // 서버로 응답(response) 받은 데이터가 위치 할 DataCollection의 조건 표현식. 또는 Instance Data의 XPath.
          action          : '/biz/Pc30R0RgcsdWrtCsCtrl/downloadFile.do',         // /biz/Pc10CmFileMngCtrl/downloadFile.do  // 통신 할 서버 측 URI.(브라우저 보안 정책으로 crossDomain은 지원되지 않는다.)
          method          : 'POST',                                                       // [default: post, get, urlencoded-post] get:파라메타를 url에 붙이는 방식 (HTML과 동일).
          mediatype       : 'application/json',                                           // application/json
          encoding        : 'UTF-8',                                                      // [default: utf-8, euc-kr, utf-16] 서버 측 encoding 타입 설정 (euc-kr/utf-16/utf-8)
          mode            : 'synchronous',                                               // [default: asynchronous] 서버와의 통신 방식. asynchronous:비동기식. synchronous:동기식
          processMsg      : '처리중입니다.',                                                // submission 통신 중 보여줄 메세지.
          submitDoneHandler : function(e) {
      		if(isXmlDown) {
      		    var xmlStr = e.responseText;
      		    xmlDoc = (new DOMParser()).parseFromString(xmlStr, "text/xml");
                  var xmlStrLower = xmlStr.toLowerCase();
                  var indexStr1 = "type=\"text/xsl\" href=\"";
                  var indexStr2 = ".xsl";
                  var len1 = xmlStrLower.indexOf(indexStr1);
                  var len2 = xmlStrLower.indexOf(indexStr2);
                  
                  if ( len1 > 0 && len2 > 0) {
      	            len1 += indexStr1.length;
                      len2 += indexStr2.length;
                      xslName = xmlStrLower.substring(len1,len2);
                      isXmlDown = false;
                      dma_file_info.set('file_name', xslName);
                      dma_file_info.set('file_path', xslPath+xslName);
                      com.sbm.execute(sbm_Pc30R0RgcsdWrtCsCtrl_downloadFile);
      	        } else {
      	        	ifmViewer.document.write(xmlStr);
      	        }
      	    } else {
      	        var xslStr = e.responseText;
                  var xslDoc = (new DOMParser()).parseFromString(xslStr, "text/xml");
                  var processor = new XSLTProcessor();
                  processor.importStylesheet(xslDoc);
                  var transform = processor.transformToDocument(xmlDoc);
                     //alert("!!!!transform"+transform);  
                  var xmls = new XMLSerializer();
                  var output = xmls.serializeToString(transform);
      		    
                  // 문자 인식 오류  > & < 대치 2009.03.03 조성영
                  while(output.indexOf("&lt;")>-1 || output.indexOf("&gt;")>-1 || output.indexOf("&amp;")>-1) {
      	            output = output.replace("&lt;","<");
      	            output = output.replace("&gt;",">");
      	            output = output.replace("&amp;","&");
                  }
                  
                  ifmViewer.document.open();
                  ifmViewer.document.write(output);
                  ifmViewer.document.close();
      		}
          }
      };
      
      com.sbm.create(options, '', null, false);
  	
  	  var xmlUrl = xmlPath + xmlName;
      //var xslName = "1971201.xsl";
      
      var ifmViewer = document.getElementById(ifmComp.getID()).contentWindow;
      
      //<%//브라우저 판별법 수정.  2014.03.02 김상현1(2014-W00190)%>
      if ( window.ActiveXObject || navigator.userAgent.toLowerCase().indexOf("trident") >= 0 ) {
          //viewer.document.location.href = xmlUrl;
          ifmViewer.document.location.href = xmlUrl;
      } else if(document.implementation && document.implementation.createDocument) {
          dma_file_info.set('file_name', xmlName);
      	  dma_file_info.set('file_path', xmlUrl);

          com.sbm.execute(sbm_Pc30R0RgcsdWrtCsCtrl_downloadFile);
      } else {
          // 지원되지 않는 브라우저입니다.
    	  var mesOption = {
                  msgType     : 'info',
                  msgTitle    : 'egov.message.title.web.com.complete',
                  msgCode     : 'pc30.message.info.web.com.0032'
         };
                      
         com.message.openMessage(mesOption);
      }
  }
